{"command":"cd /workspace && python3 -c "
import json
d = json.load(open('contracts/openapi.contract.json'))

def simplify_schema(s, depth=0):
    if not isinstance(s, dict):
        return s
    t = s.get('type')
    if t == 'object':
        props = s.get('properties', {})
        req = set(s.get('required', []))
        out = {}
        for k,v in props.items():
            mark = '*' if k in req else ''
            out[k+mark] = simplify_schema(v, depth+1)
        return out
    elif t == 'array':
        return [simplify_schema(s.get('items', {}), depth+1)]
    else:
        parts=[t]
        if 'format' in s: parts.append(s['format'])
        if 'enum' in s: parts.append('enum:'+','.join(map(str,s['enum'])))
        return '|'.join(str(p) for p in parts if p)

out = {}
for p, methods in d['paths'].items():
    for m, op in methods.items():
        entry = {'operationId': op.get('operationId')}
        rb = op.get('requestBody')
        if rb:
            schema = rb['content']['application/json']['schema']
            entry['request'] = simplify_schema(schema)
        # success responses
        succ = {}
        for code, resp in op.get('responses', {}).items():
            if code.startswith('2'):
                schema = resp['content']['application/json']['schema']
                succ[code] = simplify_schema(schema)
        entry['success'] = succ
        # params
        params = op.get('parameters')
        if params:
            entry['params'] = [ {'name':pp['name'],'in':pp['in'],'required':pp.get('required')} for pp in params]
        out[f'{m.upper()} {p}'] = entry

json.dump(out, open('/tmp/condensed.json','w'), indent=2)
print('ok', len(out))
"
","summary":"Generate condensed summary of API contract operations"}

