{"command":"create","path":"/workspace/backend/internal/server/events.go","file_text":"package server

import (
	"context"
	"encoding/json"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

// EventHub persists realtime events into Postgres (durable) and allows
// polling-based retrieval for the /api/events endpoint (also usable over
// WebSocket upgrade).
type EventHub struct {
	db *pgxpool.Pool
}

func NewEventHub(db *pgxpool.Pool) *EventHub {
	return &EventHub{db: db}
}

type Event struct {
	ID            int64                  `json:"id"`
	Type          string                 `json:"type"`
	EntityType    string                 `json:"entityType"`
	EntityID      string                 `json:"entityId"`
	Payload       map[string]interface{} `json:"payload"`
	CreatedAt     time.Time              `json:"createdAt"`
}

// Publish stores an event. audienceRole may be empty (broadcast to all roles).
func (h *EventHub) Publish(ctx context.Context, evType, entityType, entityID string, payload map[string]interface{}, audienceRole string, audienceUserID *string) {
	b, _ := json.Marshal(payload)
	_, _ = h.db.Exec(ctx, `INSERT INTO realtime_events (type, entity_type, entity_id, audience_role, audience_user_id, payload) VALUES ($1,$2,$3,$4,$5,$6)`,
		evType, entityType, entityID, nullableStr(audienceRole), audienceUserID, b)
}

func nullableStr(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

// Since returns events after the given cursor visible to the given role (or all if role=="").
func (h *EventHub) Since(ctx context.Context, since int64, role string, userID string) ([]Event, int64, error) {
	rows, err := h.db.Query(ctx, `SELECT id, type, entity_type, entity_id, payload, created_at FROM realtime_events
		WHERE id > $1 AND (audience_role IS NULL OR audience_role = $2) AND (audience_user_id IS NULL OR audience_user_id::text = $3)
		ORDER BY id ASC LIMIT 500`, since, role, userID)
	if err != nil {
		return nil, since, err
	}
	defer rows.Close()
	var events []Event
	cursor := since
	for rows.Next() {
		var e Event
		var payload []byte
		if err := rows.Scan(&e.ID, &e.Type, &e.EntityType, &e.EntityID, &payload, &e.CreatedAt); err != nil {
			return nil, since, err
		}
		_ = json.Unmarshal(payload, &e.Payload)
		events = append(events, e)
		cursor = e.ID
	}
	return events, cursor, nil
}
"}

{"command":"create","path":"/workspace/backend/internal/server/auth.go","file_text":"package server

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

type ctxKey string

const ctxUserKey ctxKey = "user"

type AuthUser struct {
	UserID     string
	Username   string
	Roles      []string
	ActiveRole string
	Token      string
}

func generateToken() string {
	b := make([]byte, 24)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func (s *Server) createSession(ctx context.Context, userID string, roles []string) (string, bool, error) {
	token := generateToken()
	roleSelectionRequired := true
	var activeRole *string
	if len(roles) == 1 {
		roleSelectionRequired = false
		activeRole = &roles[0]
	}
	_, err := s.DB.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role, role_selection_required, created_at, expires_at)
		VALUES ($1,$2,$3,$4, now(), now() + interval '24 hours')`, token, userID, activeRole, roleSelectionRequired)
	if err != nil {
		return "", false, err
	}
	return token, roleSelectionRequired, nil
}

func (s *Server) resolveSession(ctx context.Context, token string) (*AuthUser, error) {
	var userID, username string
	var roles []string
	var activeRole *string
	var active bool
	row := s.DB.QueryRow(ctx, `SELECT u.id, u.username, u.roles, s.active_role, u.active
		FROM sessions s JOIN users u ON u.id = s.user_id
		WHERE s.token = $1 AND (s.expires_at IS NULL OR s.expires_at > now())`, token)
	if err := row.Scan(&userID, &username, &roles, &activeRole, &active); err != nil {
		return nil, err
	}
	if !active {
		return nil, pgx.ErrNoRows
	}
	au := &AuthUser{UserID: userID, Username: username, Roles: roles, Token: token}
	if activeRole != nil {
		au.ActiveRole = *activeRole
	}
	return au, nil
}

// AuthMiddleware extracts bearer [REDACTED], resolves session, and stores AuthUser in context.
// Endpoints requiring auth call RequireAuth() to fetch it.
func (s *Server) AuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authz := r.Header.Get("Authorization")
		if strings.HasPrefix(authz, "Bearer ") {
			token := strings.TrimPrefix(authz, "Bearer ")
			if au, err := s.resolveSession(r.Context(), token); err == nil {
				ctx := context.WithValue(r.Context(), ctxUserKey, au)
				r = r.WithContext(ctx)
			}
		}
		next.ServeHTTP(w, r)
	})
}

func UserFromContext(r *http.Request) *AuthUser {
	v := r.Context().Value(ctxUserKey)
	if v == nil {
		return nil
	}
	return v.(*AuthUser)
}

func touchSessionExpiry(ctx context.Context, db interface{ Exec(context.Context, string, ...interface{}) (interface{}, error) }) {}

var _ = time.Now
"}

