{"command":"create","path":"/workspace/backend/internal/server/network.go","file_text":"package server

import (
	"context"

	"labsample/internal/util"
)

type LocationRow struct {
	ID                string
	Name              string
	Lat, Lon          float64
	CoverageKm        float64
	HandlingMinutes   int
	Active            bool
	IsCollectionPoint bool
	IsTransferPoint   bool
	IsHub             bool
	IsLaboratory      bool
}

func (s *Server) loadActiveLocations(ctx context.Context) ([]LocationRow, error) {
	rows, err := s.DB.Query(ctx, `SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active,
		is_collection_point, is_transfer_point, is_hub, is_laboratory FROM locations WHERE active = true`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []LocationRow
	for rows.Next() {
		var l LocationRow
		if err := rows.Scan(&l.ID, &l.Name, &l.Lat, &l.Lon, &l.CoverageKm, &l.HandlingMinutes, &l.Active,
			&l.IsCollectionPoint, &l.IsTransferPoint, &l.IsHub, &l.IsLaboratory); err != nil {
			return nil, err
		}
		out = append(out, l)
	}
	return out, nil
}

// nearestCollectionPoint returns the nearest active collection point within its coverage radius.
func nearestCollectionPoint(locs []LocationRow, lat, lon float64) *LocationRow {
	var best *LocationRow
	bestDist := 1e18
	for i := range locs {
		l := &locs[i]
		if !l.IsCollectionPoint || !l.Active {
			continue
		}
		d := util.HaversineKm(lat, lon, l.Lat, l.Lon)
		if d <= l.CoverageKm && d < bestDist {
			bestDist = d
			best = l
		}
	}
	return best
}

type ConnectionRow struct {
	ID             string
	FromID, ToID   string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
	Active         bool
}

func (s *Server) loadActiveConnections(ctx context.Context) ([]ConnectionRow, error) {
	rows, err := s.DB.Query(ctx, `SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active
		FROM connections WHERE active = true`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []ConnectionRow
	for rows.Next() {
		var c ConnectionRow
		if err := rows.Scan(&c.ID, &c.FromID, &c.ToID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, nil
}

// shortestPath computes minimal travel-minutes path between from and to using
// available connections (both directions traversable), optionally requiring
// cooled connections. Returns ordered location IDs (including from & to) and
// the connection IDs used, or nil if no route.
func shortestPath(conns []ConnectionRow, from, to string, needCooled bool) ([]string, []string, int) {
	type edge struct {
		to     string
		connID string
		weight int
		cooled bool
	}
	adj := map[string][]edge{}
	for _, c := range conns {
		if needCooled && !c.Cooled {
			continue
		}
		adj[c.FromID] = append(adj[c.FromID], edge{c.ToID, c.ID, c.TravelMinutes, c.Cooled})
		adj[c.ToID] = append(adj[c.ToID], edge{c.FromID, c.ID, c.TravelMinutes, c.Cooled})
	}
	if from == to {
		return []string{from}, nil, 0
	}
	const inf = 1 << 30
	dist := map[string]int{from: 0}
	prevLoc := map[string]string{}
	prevConn := map[string]string{}
	visited := map[string]bool{}
	for {
		// pick unvisited node with min dist
		cur := ""
		curDist := inf
		for k, d := range dist {
			if !visited[k] && d < curDist {
				cur = k
				curDist = d
			}
		}
		if cur == "" {
			break
		}
		if cur == to {
			break
		}
		visited[cur] = true
		for _, e := range adj[cur] {
			nd := curDist + e.weight
			if ed, ok := dist[e.to]; !ok || nd < ed {
				dist[e.to] = nd
				prevLoc[e.to] = cur
				prevConn[e.to] = e.connID
			}
		}
	}
	if _, ok := dist[to]; !ok {
		return nil, nil, 0
	}
	// reconstruct
	var pathLoc []string
	var pathConn []string
	cur := to
	for cur != from {
		pathLoc = append([]string{cur}, pathLoc...)
		pathConn = append([]string{prevConn[cur]}, pathConn...)
		cur = prevLoc[cur]
	}
	pathLoc = append([]string{from}, pathLoc...)
	return pathLoc, pathConn, dist[to]
}
"}

{"command":"create","path":"/workspace/backend/internal/server/capacity.go","file_text":"package server

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"
)

type CapacityRow struct {
	CapacityUnits       int
	ReservedUnits       int
	AvailableUnits      int
	CooledCapacityUnits int
	CooledReservedUnits int
	CooledAvailable     int
}

func (s *Server) getOrCreateCapacity(ctx context.Context, resourceType, resourceID string) (CapacityRow, error) {
	var c CapacityRow
	row := s.DB.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM capacities WHERE resource_type=$1 AND resource_id=$2`, resourceType, resourceID)
	err := row.Scan(&c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits)
	if errors.Is(err, pgx.ErrNoRows) {
		_, err2 := s.DB.Exec(ctx, `INSERT INTO capacities (resource_type, resource_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
			VALUES ($1,$2,0,0,0,0) ON CONFLICT DO NOTHING`, resourceType, resourceID)
		if err2 != nil {
			return c, err2
		}
		return CapacityRow{}, nil
	}
	if err != nil {
		return c, err
	}
	c.AvailableUnits = c.CapacityUnits - c.ReservedUnits
	c.CooledAvailable = c.CooledCapacityUnits - c.CooledReservedUnits
	return c, nil
}

// reserveCapacity attempts to reserve 1 unit (regular or cooled) atomically; returns ok.
func (s *Server) reserveCapacity(ctx context.Context, resourceType, resourceID string, cooled bool, units int) (bool, error) {
	if units <= 0 {
		units = 1
	}
	var sql string
	if cooled {
		sql = `UPDATE capacities SET reserved_units = reserved_units,
			cooled_reserved_units = cooled_reserved_units + $3
			WHERE resource_type=$1 AND resource_id=$2 AND (cooled_capacity_units - cooled_reserved_units) >= $3`
	} else {
		sql = `UPDATE capacities SET reserved_units = reserved_units + $3
			WHERE resource_type=$1 AND resource_id=$2 AND (capacity_units - reserved_units) >= $3`
	}
	tag, err := s.DB.Exec(ctx, sql, resourceType, resourceID, units)
	if err != nil {
		return false, err
	}
	return tag.RowsAffected() > 0, nil
}

func (s *Server) releaseCapacity(ctx context.Context, resourceType, resourceID string, cooled bool, units int) error {
	if units <= 0 {
		units = 1
	}
	var sql string
	if cooled {
		sql = `UPDATE capacities SET cooled_reserved_units = GREATEST(0, cooled_reserved_units - $3)
			WHERE resource_type=$1 AND resource_id=$2`
	} else {
		sql = `UPDATE capacities SET reserved_units = GREATEST(0, reserved_units - $3)
			WHERE resource_type=$1 AND resource_id=$2`
	}
	_, err := s.DB.Exec(ctx, sql, resourceType, resourceID, units)
	return err
}
"}

{"command":"create","path":"/workspace/backend/internal/server/handlers_auth.go","file_text":"package server

import (
