	if u == nil {
		return
	}
	if u.ActiveRole != RoleAdministrator && u.UserID != userID {
		WriteErr(w, http.StatusForbidden, "forbidden", "cannot view another user")
		return
	}
	var username string
	var email, fullName, phone *string
	var roles, quals []string
	var certs []byte
	var active bool
	row := s.DB.QueryRow(r.Context(), `SELECT username, email, full_name, phone, roles, qualifications, certifications, active FROM users WHERE id=$1`, userID)
