{"command":"create","path":"/workspace/backend/internal/server/jsonhelpers.go","file_text":"package server

import "encoding/json"

func marshalOrEmptyArray(v interface{}) []byte {
	if v == nil {
		return []byte("[]")
	}
	b, err := json.Marshal(v)
	if err != nil {
		return []byte("[]")
	}
	return b
}

func rawJSONOrEmpty(b []byte) interface{} {
	if len(b) == 0 {
		return []interface{}{}
	}
	var v interface{}
	if err := json.Unmarshal(b, &v); err != nil {
		return []interface{}{}
	}
	return v
}
"}

