{"command":"create","path":"/workspace/backend/internal/server/serviceability.go","file_text":"package server

import (
	"context"
	"encoding/json"
	"sync"
	"time"

	"labsample/internal/util"
)

// ServiceabilitySnapshot holds a complete, published snapshot of the network's
// serviceability regions. Requests are always checked against the latest
// COMPLETE snapshot, never a partially computed one.
type ServiceabilitySnapshot struct {
	Version                    int                      `json:"version"`
	Status                     string                   `json:"status"`
	ComputedAt                 time.Time                `json:"computedAt"`
	NetworkRevision            int                      `json:"networkRevision"`
	Regions                    []map[string]interface{} `json:"regions"`
	ActiveCollectionPointCount int                      `json:"activeCollectionPointCount"`
}

var snapMu sync.RWMutex
var currentSnapshot *ServiceabilitySnapshot

func (s *Server) CurrentSnapshot() *ServiceabilitySnapshot {
	snapMu.RLock()
	defer snapMu.RUnlock()
	return currentSnapshot
}

// recomputeServiceability builds a new snapshot from active collection points
// and publishes it atomically once complete. Older snapshot keeps serving
// concurrent readers until this finishes.
func (s *Server) recomputeServiceability(ctx context.Context) {
	locs, err := s.loadActiveLocations(ctx)
	if err != nil {
		return
	}
	var regions []map[string]interface{}
	count := 0
	for _, l := range locs {
		if l.IsCollectionPoint && l.Active {
			count++
			regions = append(regions, map[string]interface{}{
				"locationId": l.ID, "name": l.Name, "latitude": l.Lat, "longitude": l.Lon, "coverageKm": l.CoverageKm,
			})
		}
	}
	var revision int
	_ = s.DB.QueryRow(ctx, `SELECT revision FROM network_revision WHERE id=1`).Scan(&revision)

	var nextVersion int
	_ = s.DB.QueryRow(ctx, `SELECT COALESCE(MAX(version),0)+1 FROM serviceability_snapshots`).Scan(&nextVersion)

	snap := &ServiceabilitySnapshot{
		Version: nextVersion, Status: "complete", ComputedAt: util.NowUTC(),
		NetworkRevision: revision, Regions: regions, ActiveCollectionPointCount: count,
	}
	regionsJSON, _ := json.Marshal(regions)
	_, _ = s.DB.Exec(ctx, `INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
		VALUES ($1,$2,$3,$4,$5,$6)`, snap.Version, snap.Status, snap.ComputedAt, snap.NetworkRevision, regionsJSON, snap.ActiveCollectionPointCount)

	snapMu.Lock()
	currentSnapshot = snap
	snapMu.Unlock()
}

func (s *Server) ensureSnapshotLoaded(ctx context.Context) {
	if s.CurrentSnapshot() != nil {
		return
	}
	var version, revision, count int
	var computedAt time.Time
	var regionsRaw []byte
	err := s.DB.QueryRow(ctx, `SELECT version, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).Scan(&version, &computedAt, &revision, &regionsRaw, &count)
	if err != nil {
		s.recomputeServiceability(ctx)
		return
	}
	var regions []map[string]interface{}
	_ = json.Unmarshal(regionsRaw, &regions)
	snapMu.Lock()
	currentSnapshot = &ServiceabilitySnapshot{Version: version, Status: "complete", ComputedAt: computedAt, NetworkRevision: revision, Regions: regions, ActiveCollectionPointCount: count}
	snapMu.Unlock()
}
"}

{"command":"create","path":"/workspace/backend/internal/server/handlers_serviceability.go","file_text":"package server

import (
	"context"
	"net/http"
	"time"

	"labsample/internal/util"
)

type checkServiceabilityReq struct {
	Origin              coordinateReq `json:"origin"`
	OriginType          string        `json:"originType"`
	OriginNodeID        *string       `json:"originNodeId"`
	SampleTypeID        string        `json:"sampleTypeId"`
	RequestedAt         string        `json:"requestedAt"`
	DeliveryDeadline    string        `json:"deliveryDeadline"`
	EarliestCollectionAt string       `json:"earliestCollectionAt"`
	LatestCollectionAt  string        `json:"latestCollectionAt"`
}

type ServiceabilityResult struct {
	Serviceable          bool
	Reason               string
	TargetLaboratoryID   string
	EstimatedArrivalAt   *time.Time
}

// evaluateServiceability is a pure function of network structure (not worker
// availability) used both by the dry-run check and by request creation.
func (s *Server) evaluateServiceability(ctx context.Context, origin coordinateReq, originType string, originNodeID *string,
	sampleTypeID string, deliveryDeadline time.Time) ServiceabilityResult {

	locs, err := s.loadActiveLocations(ctx)
	if err != nil {
		return ServiceabilityResult{Serviceable: false, Reason: "no_route"}
	}
	conns, err := s.loadActiveConnections(ctx)
	if err != nil {
		return ServiceabilityResult{Serviceable: false, Reason: "no_route"}
	}

	var startLocID string
	var startLat, startLon float64
	if originType == "node" && originNodeID != nil {
		found := false
		for _, l := range locs {
			if l.ID == *originNodeID {
				startLocID = l.ID
				startLat, startLon = l.Lat, l.Lon
				found = true
				break
			}
		}
		if !found {
			return ServiceabilityResult{Serviceable: false, Reason: "outside_service_coverage"}
		}
	} else {
		nearest := nearestCollectionPoint(locs, origin.Latitude, origin.Longitude)
		if nearest == nil {
			return ServiceabilityResult{Serviceable: false, Reason: "outside_service_coverage"}
		}
		startLocID = nearest.ID
		startLat, startLon = nearest.Lat, nearest.Lon
	}
	_ = startLat
	_ = startLon

	// sample type handling rules
	var requiresCooled bool
	err = s.DB.QueryRow(ctx, `SELECT requires_cooled_route FROM sample_types WHERE id=$1`, sampleTypeID).Scan(&requiresCooled)
	if err != nil {
		return ServiceabilityResult{Serviceable: false, Reason: "handling_rules_unsatisfiable"}
	}

	// find any active laboratory accepting this sample type reachable from startLocID
	rows, err := s.DB.Query(ctx, `SELECT laboratory_id FROM laboratory_acceptance WHERE sample_type_id=$1 AND accepts=true`, sampleTypeID)
	if err != nil {
		return ServiceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory"}
	}
	var labIDs []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err == nil {
			labIDs = append(labIDs, id)
		}
	}
	rows.Close()
	if len(labIDs) == 0 {
		return ServiceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory"}
	}

	activeLabSet := map[string]bool{}
	for _, l := range locs {
		if l.IsLaboratory && l.Active {
			activeLabSet[l.ID] = true
		}
	}

	bestArrival := time.Time{}
	bestLab := ""
	found := false
	for _, labID := range labIDs {
		if !activeLabSet[labID] {
			continue
		}
		_, _, minutes := shortestPath(conns, startLocID, labID, requiresCooled)
		if minutes == 0 && startLocID != labID {
			continue
		}
		arrival := util.NowUTC().Add(time.Duration(minutes) * time.Minute)
		if !found || arrival.Before(bestArrival) {
			bestArrival = arrival
			bestLab = labID
			found = true
		}
	}
	if !found {
		return ServiceabilityResult{Serviceable: false, Reason: "no_route"}
	}
	if bestArrival.After(deliveryDeadline) {
		return ServiceabilityResult{Serviceable: false, Reason: "deadline_unreachable", TargetLaboratoryID: bestLab, EstimatedArrivalAt: &bestArrival}
	}

	// capacity check: at least one unit of relevant capacity available at destination lab
	cap, err := s.getOrCreateCapacity(ctx, "location", bestLab)
	if err == nil {
		if requiresCooled {
			if cap.CooledCapacityUnits > 0 && cap.CooledAvailable <= 0 {
				return ServiceabilityResult{Serviceable: false, Reason: "insufficient_capacity", TargetLaboratoryID: bestLab}
			}
		} else {
			if cap.CapacityUnits > 0 && cap.AvailableUnits <= 0 {
				return ServiceabilityResult{Serviceable: false, Reason: "insufficient_capacity", TargetLaboratoryID: bestLab}
			}
		}
	}

	return ServiceabilityResult{Serviceable: true, Reason: "serviceable", TargetLaboratoryID: bestLab, EstimatedArrivalAt: &bestArrival}
}

func (s *Server) HandleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleRequester, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req checkServiceabilityReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.SampleTypeID == "" || req.RequestedAt == "" || req.DeliveryDeadline == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "sampleTypeId, requestedAt, deliveryDeadline required")
		return
	}
	deadline, err := util.ParseTime(req.DeliveryDeadline)
	if err != nil {
		WriteErr(w, http.StatusBadRequest, "invalid_deadline", "invalid deliveryDeadline")
		return
	}
	if req.EarliestCollectionAt != "" && req.LatestCollectionAt != "" {
		early, e1 := util.ParseTime(req.EarliestCollectionAt)
		late, e2 := util.ParseTime(req.LatestCollectionAt)
		if e1 != nil || e2 != nil || late.Before(early) {
			WriteErr(w, http.StatusBadRequest, "invalid_collection_window", "invalid collection window")
			return
		}
	}
	originType := req.OriginType
	if originType == "" {
		originType = "home"
	}
	if originType != "home" && originType != "clinic" && originType != "node" {
		WriteErr(w, http.StatusBadRequest, "invalid_origin_type", "invalid originType")
		return
	}

	s.ensureSnapshotLoaded(r.Context())
	snap := s.CurrentSnapshot()
	version := 1
	if snap != nil {
		version = snap.Version
	}

	result := s.evaluateServiceability(r.Context(), req.Origin, originType, req.OriginNodeID, req.SampleTypeID, deadline)

	s.Audit(r.Context(), u.UserID, u.ActiveRole, "check_serviceability", "serviceability", req.SampleTypeID, true, map[string]interface{}{
		"serviceable": result.Serviceable, "reason": result.Reason,
	})

	resp := map[string]interface{}{
		"serviceable":          result.Serviceable,
		"reason":               result.Reason,
		"serviceabilityVersion": version,
	}
	if result.TargetLaboratoryID != "" {
		resp["targetLaboratoryId"] = result.TargetLaboratoryID
	}
	if result.EstimatedArrivalAt != nil {
		resp["estimatedArrivalAt"] = result.EstimatedArrivalAt.Format(time.RFC3339)
	}
	WriteData(w, http.StatusOK, resp)
}

func (s *Server) HandleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator, RoleRequester)
	if u == nil {
		return
	}
	s.ensureSnapshotLoaded(r.Context())
	snap := s.CurrentSnapshot()
	if snap == nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", "no snapshot available")
		return
	}
	WriteData(w, http.StatusOK, map[string]interface{}{
		"version": snap.Version, "status": snap.Status, "computedAt": snap.ComputedAt.Format(time.RFC3339),
		"networkRevision": snap.NetworkRevision, "regions": snap.Regions, "activeCollectionPointCount": snap.ActiveCollectionPointCount,
	})
}
"}

