{"command":"create","path":"/workspace/backend/internal/server/handlers_assignments.go","file_text":"package server

import (
	"net/http"

	"labsample/internal/util"
)

type acceptAssignmentReq struct {
	AssignmentID   string `json:"assignmentId"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) HandleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req acceptAssignmentReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.AssignmentID == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "assignmentId and idempotencyKey required")
		return
	}
	var status string
	var offeredWorker *string
	row := s.DB.QueryRow(r.Context(), `SELECT status, offered_worker_id FROM assignments WHERE id=$1`, req.AssignmentID)
	if err := row.Scan(&status, &offeredWorker); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if status != "offered" {
		WriteErr(w, http.StatusConflict, "offer_not_available", "assignment is not currently offered")
		return
	}
	if offeredWorker == nil || *offeredWorker != u.UserID {
		WriteErr(w, http.StatusForbidden, "ineligible_worker", "assignment was not offered to this worker")
		return
	}
	tag, err := s.DB.Exec(r.Context(), `UPDATE assignments SET status='accepted', worker_id=$1, updated_at=now() WHERE id=$2 AND status='offered'`, u.UserID, req.AssignmentID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if tag.RowsAffected() == 0 {
		WriteErr(w, http.StatusConflict, "offer_not_available", "assignment already resolved")
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE users SET recent_assignment_count = recent_assignment_count + 1 WHERE id=$1`, u.UserID)
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "accept_assignment", "assignment", req.AssignmentID, true, nil)
	WriteData(w, http.StatusCreated, map[string]interface{}{"assignmentId": req.AssignmentID, "workerId": u.UserID, "status": "accepted"})
}

type declineAssignmentReq struct {
	AssignmentID   string `json:"assignmentId"`
	Reason         string `json:"reason"`
	DeclinedAt     string `json:"declinedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) HandleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req declineAssignmentReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.AssignmentID == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "assignmentId and idempotencyKey required")
		return
	}
	var status string
	var offeredWorker *string
	row := s.DB.QueryRow(r.Context(), `SELECT status, offered_worker_id FROM assignments WHERE id=$1`, req.AssignmentID)
	if err := row.Scan(&status, &offeredWorker); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if status != "offered" {
		WriteErr(w, http.StatusConflict, "offer_not_available", "assignment is not currently offered")
		return
	}
	if offeredWorker == nil || *offeredWorker != u.UserID {
		WriteErr(w, http.StatusForbidden, "ineligible_worker", "assignment was not offered to this worker")
		return
	}
	_, err := s.DB.Exec(r.Context(), `UPDATE assignments SET status='pending', offered_worker_id=NULL, offer_expires_at=NULL,
		declined_worker_ids = array_append(declined_worker_ids, $1), updated_at=now() WHERE id=$2`, u.UserID, req.AssignmentID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE users SET decline_count = decline_count + 1, priority_penalty_until = now() + interval '30 minutes' WHERE id=$1`, u.UserID)
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "decline_assignment", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})

	s.tryOfferAssignment(r.Context(), req.AssignmentID)
	var reofferedTo *string
	_ = s.DB.QueryRow(r.Context(), `SELECT offered_worker_id FROM assignments WHERE id=$1`, req.AssignmentID).Scan(&reofferedTo)

	resp := map[string]interface{}{
		"assignmentId": req.AssignmentID, "status": "pending", "declinedBy": u.UserID, "declinedAt": util.NowUTC().Format("2006-01-02T15:04:05Z07:00"),
	}
	if reofferedTo != nil {
		resp["reofferedTo"] = *reofferedTo
	}
	WriteData(w, http.StatusCreated, resp)
}
"}

{"command":"create","path":"/workspace/backend/internal/server/handlers_sample_lifecycle.go","file_text":"package server

import (
	"net/http"
	"time"

	"github.com/google/uuid"
	"labsample/internal/util"
)

type collectAndSealReq struct {
	SampleID             string  `json:"sampleId"`
	AssignmentID         string  `json:"assignmentId"`
	CollectedAt          string  `json:"collectedAt"`
	ContainerType        string  `json:"containerType"`
	ObservedTemperatureC float64 `json:"observedTemperatureC"`
	IdempotencyKey       string  `json:"idempotencyKey"`
}

func (s *Server) HandleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf)
	if u == nil {
		return
	}
	var req collectAndSealReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.SampleID == "" || req.AssignmentID == "" || req.CollectedAt == "" || req.ContainerType == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "missing required fields")
		return
	}
	var assignedWorker *string
	var kind, astatus string
	row := s.DB.QueryRow(r.Context(), `SELECT worker_id, kind, status FROM assignments WHERE id=$1 AND sample_id=$2`, req.AssignmentID, req.SampleID)
	if err := row.Scan(&assignedWorker, &kind, &astatus); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if kind != "collection" || assignedWorker == nil || *assignedWorker != u.UserID {
		WriteErr(w, http.StatusForbidden, "ineligible_worker", "not assigned to this collection")
		return
	}
	var tmin, tmax float64
	var containerReq string
	_ = s.DB.QueryRow(r.Context(), `SELECT temperature_min_c, temperature_max_c, container_type FROM requests req
		JOIN samples sam ON sam.request_id = req.id WHERE sam.id=$1`, req.SampleID).Scan(&tmin, &tmax, &containerReq)
	compliant := req.ObservedTemperatureC >= tmin && req.ObservedTemperatureC <= tmax && req.ContainerType == containerReq

	collectedAt, err := util.ParseTime(req.CollectedAt)
	if err != nil {
		collectedAt = util.NowUTC()
	}

	status := "sealed"
	var exceptionJSON interface{}
	if !compliant {
		status = "exception"
		exceptionJSON = map[string]interface{}{"reason": "handling_out_of_range", "observedTemperatureC": req.ObservedTemperatureC, "containerType": req.ContainerType}
	}

	_, err = s.DB.Exec(r.Context(), `UPDATE samples SET status=$1, sealed=true, sealed_at=$2, current_holder_id=$3, exception=$4, updated_at=now() WHERE id=$5`,
		status, collectedAt, u.UserID, marshalOrEmptyArray(exceptionJSON), req.SampleID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE assignments SET status='completed', updated_at=now() WHERE id=$1`, req.AssignmentID)
	_, _ = s.DB.Exec(r.Context(), `INSERT INTO handling_checkpoints (sample_id, assignment_id, container_type, observed_temperature_c, compliant, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6)`, req.SampleID, req.AssignmentID, req.ContainerType, req.ObservedTemperatureC, compliant, collectedAt)

	s.Audit(r.Context(), u.UserID, u.ActiveRole, "collect_and_seal_sample", "sample", req.SampleID, true, map[string]interface{}{"compliant": compliant})
	s.Events.Publish(r.Context(), "sample.sealed", "sample", req.SampleID, map[string]interface{}{"sampleId": req.SampleID, "status": status}, "dispatcher", nil)

	WriteData(w, http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "status": "sealed", "currentHolderId": u.UserID,
		"sealedAt": collectedAt.Format(time.RFC3339), "handlingCompliant": compliant,
	})
}

type initiateHandoffReq struct {
	SampleID        string `json:"sampleId"`
	FromAssignmentID string `json:"fromAssignmentId"`
	ToAssignmentID   string `json:"toAssignmentId"`
	ReceiverID       string `json:"receiverId"`
