type confirmHandoffReq struct {
	HandoffID        string `json:"handoffId"`
	ConfirmationSide string `json:"confirmationSide"`
	ConfirmedAt      string `json:"confirmedAt"`
	IdempotencyKey   string `json:"idempotencyKey"`
}

func (s *Server) HandleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req confirmHandoffReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.HandoffID == "" || req.ConfirmationSide == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "missing required fields")
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "confirmationSide must be sender or receiver")
		return
	}
	var senderID, receiverID, sampleID, status string
	var senderConfirmed, receiverConfirmed bool
	var toAssignment *string
	row := s.DB.QueryRow(r.Context(), `SELECT sender_id, receiver_id, sample_id, status, sender_confirmed, receiver_confirmed, to_assignment_id FROM handoffs WHERE id=$1`, req.HandoffID)
	if err := row.Scan(&senderID, &receiverID, &sampleID, &status, &senderConfirmed, &receiverConfirmed, &toAssignment); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "handoff not found")
		return
	}
	if req.ConfirmationSide == "sender" && u.UserID != senderID {
		WriteErr(w, http.StatusForbidden, "forbidden", "not the sender")
		return
	}
	if req.ConfirmationSide == "receiver" && u.UserID != receiverID {
		WriteErr(w, http.StatusForbidden, "forbidden", "not the receiver")
		return
	}
	if req.ConfirmationSide == "sender" {
		senderConfirmed = true
	} else {
		receiverConfirmed = true
	}
	newStatus := "pending"
	var currentHolder = senderID
	if senderConfirmed && receiverConfirmed {
		newStatus = "confirmed"
		currentHolder = receiverID
	}
	_, err := s.DB.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=$1, receiver_confirmed=$2, status=$3, confirmed_at=CASE WHEN $3='confirmed' THEN now() ELSE confirmed_at END WHERE id=$4`,
		senderConfirmed, receiverConfirmed, newStatus, req.HandoffID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if newStatus == "confirmed" {
		_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, updated_at=now() WHERE id=$2`, receiverID, sampleID)
		if toAssignment != nil {
			_, _ = s.DB.Exec(r.Context(), `UPDATE assignments SET status='completed', updated_at=now() WHERE id=$1`, *toAssignment)
		}
		s.Events.Publish(r.Context(), "sample.custody_transferred", "sample", sampleID, map[string]interface{}{"sampleId": sampleID, "currentHolderId": receiverID}, "dispatcher", nil)
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "confirm_handoff", "handoff", req.HandoffID, true, map[string]interface{}{"side": req.ConfirmationSide, "status": newStatus})

	WriteData(w, http.StatusCreated, map[string]interface{}{
		"handoffId": req.HandoffID, "status": newStatus, "senderConfirmed": senderConfirmed, "receiverConfirmed": receiverConfirmed, "currentHolderId": currentHolder,
	})
}

