func (s *Server) loadLegs(ctx httpCtx, journeyID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id, sequence, status, from_location_id, to_location_id, worker_id, sample_id FROM assignments WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var id, status, sampleID string
		var seq int
		var fromLoc, toLoc, workerID *string
		if rows.Scan(&id, &seq, &status, &fromLoc, &toLoc, &workerID, &sampleID) != nil {
			continue
		}
		leg := map[string]interface{}{"assignmentId": id, "sequence": seq, "status": status, "sampleId": sampleID}
		if fromLoc != nil {
			leg["fromLocationId"] = *fromLoc
		}
		if toLoc != nil {
			leg["toLocationId"] = *toLoc
		}
		if workerID != nil {
			leg["workerId"] = *workerID
		}
		out = append(out, leg)
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out
}

func (s *Server) loadStops(ctx httpCtx, journeyID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, completed_at FROM journey_stops WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	if err != nil {
