type splitJourneyReq struct {
	JourneyID           string   `json:"journeyId"`
	ExpectedPlanVersion int      `json:"expectedPlanVersion"`
	SampleIDs           []string `json:"sampleIds"`
	IdempotencyKey      string   `json:"idempotencyKey"`
}

func (s *Server) HandleSplitJourney(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req splitJourneyReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.JourneyID == "" || req.IdempotencyKey == "" || len(req.SampleIDs) == 0 {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "journeyId, sampleIds, idempotencyKey required")
		return
	}
	var version int
	var status string
	var sampleIDs []string
	row := s.DB.QueryRow(r.Context(), `SELECT plan_version, status, sample_ids FROM journeys WHERE id=$1`, req.JourneyID)
	if err := row.Scan(&version, &status, &sampleIDs); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if version != req.ExpectedPlanVersion {
		WriteErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}
	newJourneyID := uuid.New().String()
	_, err := s.DB.Exec(r.Context(), `INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, sample_ids)
		VALUES ($1,$2,1,'direct','planned',$3)`, newJourneyID, req.JourneyID, req.SampleIDs)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	remaining := []string{}
	for _, sid := range sampleIDs {
		found := false
		for _, s2 := range req.SampleIDs {
			if sid == s2 {
				found = true
				break
			}
		}
		if !found {
			remaining = append(remaining, sid)
		}
	}
	_, err = s.DB.Exec(r.Context(), `UPDATE journeys SET sample_ids=$1, plan_version=plan_version+1, updated_at=now() WHERE id=$2`, remaining, req.JourneyID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	for _, sid := range req.SampleIDs {
		_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET active_journey_id=$1, updated_at=now() WHERE id=$2`, newJourneyID, sid)
		_, _ = s.DB.Exec(r.Context(), `UPDATE assignments SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3 AND status NOT IN ('completed','cancelled')`, newJourneyID, req.JourneyID, sid)
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "split_journey", "journey", req.JourneyID, true, map[string]interface{}{"newJourneyId": newJourneyID})
	WriteData(w, http.StatusCreated, map[string]interface{}{
		"journey":      map[string]interface{}{"journeyId": req.JourneyID, "sampleIds": remaining},
		"splitJourney": map[string]interface{}{"journeyId": newJourneyID, "sampleIds": req.SampleIDs},
	})
}

type mergeJourneysReq struct {
	TargetJourneyID     string   `json:"targetJourneyId"`
	ExpectedPlanVersion int      `json:"expectedPlanVersion"`
	SourceJourneyIDs    []string `json:"sourceJourneyIds"`
	IdempotencyKey      string   `json:"idempotencyKey"`
}

func (s *Server) HandleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req mergeJourneysReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.TargetJourneyID == "" || req.IdempotencyKey == "" || len(req.SourceJourneyIDs) == 0 {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "targetJourneyId, sourceJourneyIds, idempotencyKey required")
		return
	}
	var version int
	var targetSamples []string
	row := s.DB.QueryRow(r.Context(), `SELECT plan_version, sample_ids FROM journeys WHERE id=$1`, req.TargetJourneyID)
	if err := row.Scan(&version, &targetSamples); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "target journey not found")
		return
	}
	if version != req.ExpectedPlanVersion {
		WriteErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}
	for _, jid := range req.SourceJourneyIDs {
		var srcSamples []string
		_ = s.DB.QueryRow(r.Context(), `SELECT sample_ids FROM journeys WHERE id=$1`, jid).Scan(&srcSamples)
		targetSamples = append(targetSamples, srcSamples...)
		_, _ = s.DB.Exec(r.Context(), `UPDATE assignments SET journey_id=$1 WHERE journey_id=$2 AND status NOT IN ('completed','cancelled')`, req.TargetJourneyID, jid)
		for _, sid := range srcSamples {
			_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET active_journey_id=$1 WHERE id=$2`, req.TargetJourneyID, sid)
		}
		_, _ = s.DB.Exec(r.Context(), `UPDATE journeys SET status='merged', updated_at=now() WHERE id=$1`, jid)
	}
	_, err := s.DB.Exec(r.Context(), `UPDATE journeys SET sample_ids=$1, plan_version=plan_version+1, updated_at=now() WHERE id=$2`, targetSamples, req.TargetJourneyID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sourceJourneyIds": req.SourceJourneyIDs})
	WriteData(w, http.StatusCreated, map[string]interface{}{"journeyId": req.TargetJourneyID, "sampleIds": targetSamples})
}

type rerouteJourneyReq struct {
	JourneyID           string `json:"journeyId"`
	ExpectedPlanVersion int    `json:"expectedPlanVersion"`
	Reason              string `json:"reason"`
	IdempotencyKey      string `json:"idempotencyKey"`
}

func (s *Server) HandleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req rerouteJourneyReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.JourneyID == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "journeyId, idempotencyKey required")
		return
	}
	var version int
	var sampleIDs []string
	row := s.DB.QueryRow(r.Context(), `SELECT plan_version, sample_ids FROM journeys WHERE id=$1`, req.JourneyID)
	if err := row.Scan(&version, &sampleIDs); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if version != req.ExpectedPlanVersion {
		WriteErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}

	replanStatus := "not_required"
	var replacementJourneyID *string
	if len(sampleIDs) > 0 {
		sampleID := sampleIDs[0]
		var labID, sampleTypeID string
		_ = s.DB.QueryRow(r.Context(), `SELECT target_laboratory_id, sample_type_id FROM samples sam JOIN requests req ON req.id=sam.request_id
			WHERE sam.id=$1`, sampleID).Scan(&labID, &sampleTypeID)

		var lastLoc *string
		_ = s.DB.QueryRow(r.Context(), `SELECT to_location_id FROM assignments WHERE journey_id=$1 AND status='completed' ORDER BY sequence DESC LIMIT 1`, req.JourneyID).Scan(&lastLoc)
		start := ""
		if lastLoc != nil {
			start = *lastLoc
		}
		if start != "" && labID != "" {
			newJourneyID, _, err := s.planJourneyFromPoint(r.Context(), sampleID, start, labID, sampleTypeID)
			if err == nil && newJourneyID != "" {
				replanStatus = "replaced"
				replacementJourneyID = &newJourneyID
				_, _ = s.DB.Exec(r.Context(), `UPDATE journeys SET status='superseded', plan_version=plan_version+1, updated_at=now() WHERE id=$1`, req.JourneyID)
			} else {
				replanStatus = "expired"
				_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET status='expired', updated_at=now() WHERE id=$1`, sampleID)
			}
		} else {
			replanStatus = "exception"
		}
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "reroute_journey", "journey", req.JourneyID, true, map[string]interface{}{"replanStatus": replanStatus})
	resp := map[string]interface{}{"journeyId": req.JourneyID, "replanStatus": replanStatus}
	if replacementJourneyID != nil {
		resp["replacementPlanId"] = *replacementJourneyID
		resp["replacementJourney"] = map[string]interface{}{"journeyId": *replacementJourneyID}
	}
	WriteData(w, http.StatusCreated, resp)
}

