	s.Audit(r.Context(), u.UserID, u.ActiveRole, "edit_active_plan", "journey", req.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
	WriteData(w, http.StatusCreated, map[string]interface{}{"journeyId": req.JourneyID, "planVersion": version + 1, "changeType": req.ChangeType})
}

type reportDisruptionReq struct {
	ResourceType   string `json:"resourceType"`
	ResourceID     string `json:"resourceId"`
	Reason         string `json:"reason"`
	OccurredAt     string `json:"occurredAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) HandleReportDisruption(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req reportDisruptionReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.ResourceType == "" || req.ResourceID == "" || req.OccurredAt == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "resourceType, resourceId, occurredAt, idempotencyKey required")
		return
	}
	var affectedSamples []string
	rows, err := s.DB.Query(r.Context(), `SELECT DISTINCT sample_id FROM assignments a JOIN journeys j ON j.id=a.journey_id
		WHERE (a.from_location_id=$1 OR a.to_location_id=$1 OR a.node_id=$1 OR a.laboratory_id=$1 OR a.worker_id=$1)
		AND a.status NOT IN ('completed','cancelled') AND j.status NOT IN ('completed','cancelled')`, req.ResourceID)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var sid string
			if rows.Scan(&sid) == nil {
				affectedSamples = append(affectedSamples, sid)
			}
		}
	}
	if affectedSamples == nil {
		affectedSamples = []string{}
	}

	disruptionID := uuid.New().String()
	var replacementPlanIDs []string
	replanStatus := "not_required"
	for _, sid := range affectedSamples {
		var journeyID *string
		var labID, sampleTypeID string
		_ = s.DB.QueryRow(r.Context(), `SELECT active_journey_id FROM samples WHERE id=$1`, sid).Scan(&journeyID)
		_ = s.DB.QueryRow(r.Context(), `SELECT target_laboratory_id, sample_type_id FROM samples sam JOIN requests req ON req.id=sam.request_id WHERE sam.id=$1`, sid).Scan(&labID, &sampleTypeID)
		if journeyID == nil {
			continue
		}
		var lastLoc *string
		_ = s.DB.QueryRow(r.Context(), `SELECT to_location_id FROM assignments WHERE journey_id=$1 AND status='completed' ORDER BY sequence DESC LIMIT 1`, *journeyID).Scan(&lastLoc)
		start := ""
		if lastLoc != nil {
			start = *lastLoc
		}
		if start != "" && labID != "" {
			newJourneyID, _, err := s.planJourneyFromPoint(r.Context(), sid, start, labID, sampleTypeID)
			if err == nil && newJourneyID != "" {
				replanStatus = "replaced"
				replacementPlanIDs = append(replacementPlanIDs, newJourneyID)
				_, _ = s.DB.Exec(r.Context(), `UPDATE journeys SET status='superseded', plan_version=plan_version+1, updated_at=now() WHERE id=$1`, *journeyID)
				continue
			}
		}
		replanStatus = "expired"
		_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET status='expired', updated_at=now() WHERE id=$1`, sid)
	}
	if replacementPlanIDs == nil {
		replacementPlanIDs = []string{}
	}

	_, err = s.DB.Exec(r.Context(), `INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
		VALUES ($1,$2,$3,$4,now(),$5,$6,$7)`, disruptionID, req.ResourceType, req.ResourceID, req.Reason, affectedSamples, replacementPlanIDs, replanStatus)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"replanStatus": replanStatus})
	WriteData(w, http.StatusCreated, map[string]interface{}{
		"disruptionId": disruptionID, "affectedSampleIds": affectedSamples, "replacementPlanIds": replacementPlanIDs, "replanStatus": replanStatus,
	})
}
"}

{"command":"create","path":"/workspace/backend/internal/server/handlers_rolework.go","file_text":"package server

import (
	"net/http"
	"time"
)

type listRoleWorkReq struct {
	Role   string `json:"role"`
	Status string `json:"status"`
}

func (s *Server) HandleListRoleWork(w http.ResponseWriter, r *http.Request) {
	u := RequireAuth(w, r)
	if u == nil {
		return
	}
	var req listRoleWorkReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	role := req.Role
	if role == "" {
		role = u.ActiveRole
	}
	if role != u.ActiveRole {
		WriteErr(w, http.StatusForbidden, "forbidden", "role must match active role")
		return
	}
	if role == "" {
		WriteErr(w, http.StatusConflict, "role_not_selected", "an active role must be selected")
		return
	}

	pending := []map[string]interface{}{}
	inProgress := []map[string]interface{}{}
	completed := []map[string]interface{}{}

	switch role {
	case RoleRequester:
		rows, err := s.DB.Query(r.Context(), `SELECT sam.id, sam.status, sam.serviceability, req.id, req.requested_at, req.delivery_deadline,
			req.earliest_collection_at, req.latest_collection_at, sam.active_journey_id, sam.target_laboratory_id, sam.current_holder_id
			FROM samples sam JOIN requests req ON req.id = sam.request_id WHERE req.requester_id=$1 ORDER BY req.requested_at DESC`, u.UserID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var sampleID, status, serviceability, requestID string
				var requestedAt, deadline time.Time
				var earliest, latest *time.Time
				var journeyID, labID, holder *string
				if rows.Scan(&sampleID, &status, &serviceability, &requestID, &requestedAt, &deadline, &earliest, &latest, &journeyID, &labID, &holder) != nil {
					continue
				}
				item := map[string]interface{}{
					"kind": "sample", "sampleId": sampleID, "requestId": requestID, "status": status, "serviceability": serviceability,
					"requestedAt": requestedAt.Format(time.RFC3339), "deliveryDeadline": deadline.Format(time.RFC3339),
					"history": s.sampleTimeline(r.Context(), sampleID), "locationStale": true,
				}
				if earliest != nil {
					item["earliestCollectionAt"] = earliest.Format(time.RFC3339)
				}
				if latest != nil {
					item["latestCollectionAt"] = latest.Format(time.RFC3339)
				}
				if journeyID != nil {
					item["journeyId"] = *journeyID
					item["activeJourneyId"] = *journeyID
				}
				if labID != nil {
					item["laboratoryId"] = *labID
				}
				if holder != nil {
					item["currentHolderId"] = *holder
				}
				switch status {
				case "received", "cancelled", "expired":
					completed = append(completed, item)
				case "pending_collection":
					pending = append(pending, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	default:
		// worker roles: assignments offered/accepted/in_progress -> pending/inProgress; completed -> completed
		var whereClause string
		switch role {
		case RoleCollectionProf:
			whereClause = `a.kind='collection'`
		case RoleDeliveryPartner:
			whereClause = `a.kind='transport'`
		case RoleNodeHandler:
			whereClause = `a.kind='node'`
		case RoleLaboratoryTeam:
			whereClause = `a.kind='laboratory'`
		case RoleDispatcher, RoleAdministrator:
			whereClause = `true`
		}
		rows, err := s.DB.Query(r.Context(), `SELECT a.id, a.status, a.sample_id, a.journey_id, a.from_location_id, a.to_location_id, a.sequence, a.offer_expires_at,
			a.node_id, a.laboratory_id, a.expected_sample_type_id
			FROM assignments a WHERE (a.worker_id=$1 OR a.offered_worker_id=$1) AND (`+whereClause+`) ORDER BY a.created_at DESC`, u.UserID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, status, sampleID, journeyID string
				var fromLoc, toLoc, nodeID, labID, expType *string
				var seq int
				var offerExp *time.Time
				if rows.Scan(&id, &status, &sampleID, &journeyID, &fromLoc, &toLoc, &seq, &offerExp, &nodeID, &labID, &expType) != nil {
					continue
				}
				item := map[string]interface{}{
					"kind": "transport", "assignmentId": id, "sampleId": sampleID, "status": status, "journeyId": journeyID,
					"sequence": seq, "history": s.sampleTimeline(r.Context(), sampleID),
				}
				if fromLoc != nil {
					item["fromLocationId"] = *fromLoc
				}
				if toLoc != nil {
					item["toLocationId"] = *toLoc
				}
				if nodeID != nil {
					item["nodeId"] = *nodeID
				}
				if labID != nil {
					item["laboratoryId"] = *labID
				}
				if expType != nil {
					item["expectedSampleTypeId"] = *expType
				}
				if offerExp != nil {
					item["offerExpiresAt"] = offerExp.Format(time.RFC3339)
				}
				switch status {
				case "completed", "cancelled":
					completed = append(completed, item)
				case "offered", "pending":
					pending = append(pending, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	}

	if req.Status != "" {
		filterFn := func(items []map[string]interface{}) []map[string]interface{} {
			out := []map[string]interface{}{}
			for _, it := range items {
				if it["status"] == req.Status {
					out = append(out, it)
				}
			}
			return out
		}
		pending = filterFn(pending)
		inProgress = filterFn(inProgress)
		completed = filterFn(completed)
	}

	WriteData(w, http.StatusOK, map[string]interface{}{"pending": pending, "inProgress": inProgress, "completed": completed})
}
"}

{"command":"create","path":"/workspace/backend/internal/server/handlers_operations.go","file_text":"package server

import (
	"net/http"
	"time"
)

type readOpsStateReq struct {
	Filters map[string]interface{} `json:"filters"`
}

func (s *Server) HandleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req readOpsStateReq
	_ = DecodeJSON(w, r, &req)

	samples := []map[string]interface{}{}
	rows, err := s.DB.Query(r.Context(), `SELECT sam.id, sam.status, req.id, req.origin_lat, req.origin_lon, req.delivery_deadline,
		sam.current_holder_id, sam.active_journey_id, sam.latest_lat, sam.latest_lon, sam.location_recorded_at
		FROM samples sam JOIN requests req ON req.id = sam.request_id`)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var sampleID, status, requestID string
			var olat, olon float64
			var deadline time.Time
			var holder, journeyID *string
			var latLat, latLon *float64
			var locRec *time.Time
			if rows.Scan(&sampleID, &status, &requestID, &olat, &olon, &deadline, &holder, &journeyID, &latLat, &latLon, &locRec) != nil {
				continue
			}
			stale := locRec == nil || time.Since(*locRec) > 30*time.Minute
			m := map[string]interface{}{
				"sampleId": sampleID, "status": status, "requestId": requestID,
				"origin": map[string]interface{}{"latitude": olat, "longitude": olon},
				"deliveryDeadline": deadline.Format(time.RFC3339), "locationStale": stale,
			}
			if holder != nil {
				m["currentHolderId"] = *holder
			}
			if journeyID != nil {
				m["activeJourneyId"] = *journeyID
			}
			if latLat != nil && latLon != nil {
				m["latestLocation"] = map[string]interface{}{"latitude": *latLat, "longitude": *latLon}
			}
			if locRec != nil {
				m["locationRecordedAt"] = locRec.Format(time.RFC3339)
			}
			samples = append(samples, m)
		}
	}

	workers := []map[string]interface{}{}
	wrows, err := s.DB.Query(r.Context(), `SELECT id, full_name, roles, active, recent_assignment_count FROM users
		WHERE roles && ARRAY['collection_professional','delivery_partner','node_handler','laboratory_team']::text[]`)
	if err == nil {
		defer wrows.Close()
		for wrows.Next() {
			var id string
			var fullName *string
			var roles []string
			var active bool
			var count int
			if wrows.Scan(&id, &fullName, &roles, &active, &count) != nil {
				continue
			}
			var latLat, latLon *float64
			var recAt *time.Time
			_ = s.DB.QueryRow(r.Context(), `SELECT latitude, longitude, recorded_at FROM worker_locations WHERE worker_id=$1 ORDER BY sequence DESC, id DESC LIMIT 1`, id).Scan(&latLat, &latLon, &recAt)
			stale := recAt == nil || time.Since(*recAt) > 30*time.Minute
			status := "unavailable"
			if active {
				status = "available"
			}
			m := map[string]interface{}{
				"workerId": id, "roles": roles, "available": active, "status": status,
				"capacityUnits": count, "assignmentCount": count, "locationStale": stale,
			}
			if fullName != nil {
				m["fullName"] = *fullName
			}
			if latLat != nil && latLon != nil {
				m["latestLocation"] = map[string]interface{}{"latitude": *latLat, "longitude": *latLon}
			}
			if recAt != nil {
				m["locationRecordedAt"] = recAt.Format(time.RFC3339)
			}
			workers = append(workers, m)
		}
	}

	locations := []map[string]interface{}{}
	lrows, err := s.DB.Query(r.Context(), `SELECT id, name, latitude, longitude, active, coverage_km, handling_minutes,
		is_collection_point, is_transfer_point, is_hub, is_laboratory FROM locations`)
	if err == nil {
		defer lrows.Close()
		for lrows.Next() {
			var id, name string
			var lat, lon, coverage float64
			var handling int
			var active, cp, tp, hub, lab bool
			if lrows.Scan(&id, &name, &lat, &lon, &active, &coverage, &handling, &cp, &tp, &hub, &lab) != nil {
				continue
			}
			cap, _ := s.getOrCreateCapacity(r.Context(), "location", id)
			m := map[string]interface{}{
				"id": id, "locationId": id, "name": name, "coordinate": map[string]interface{}{"latitude": lat, "longitude": lon},
				"active": active, "coverageKm": coverage, "handlingMinutes": handling,
				"functions": map[string]interface{}{"collection_point": cp, "transfer_point": tp, "hub": hub, "laboratory": lab},
				"capacity": map[string]interface{}{
					"capacityUnits": cap.CapacityUnits, "reservedUnits": cap.ReservedUnits, "availableUnits": cap.AvailableUnits,
					"cooledCapacityUnits": cap.CooledCapacityUnits, "cooledReservedUnits": cap.CooledReservedUnits, "cooledAvailableUnits": cap.CooledAvailable,
				},
			}
			locations = append(locations, m)
		}
	}

	connections := []map[string]interface{}{}
	crows, err := s.DB.Query(r.Context(), `SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections`)
	if err == nil {
		defer crows.Close()
		for crows.Next() {
			var id, from, to string
			var minutes int
			var cost float64
			var cooled, active bool
			if crows.Scan(&id, &from, &to, &minutes, &cost, &cooled, &active) != nil {
				continue
			}
			cap, _ := s.getOrCreateCapacity(r.Context(), "connection", id)
			connections = append(connections, map[string]interface{}{
				"id": id, "connectionId": id, "fromLocationId": from, "toLocationId": to,
				"travelMinutes": minutes, "costUnits": cost, "cooled": cooled, "active": active,
				"capacity": map[string]interface{}{
					"capacityUnits": cap.CapacityUnits, "reservedUnits": cap.ReservedUnits, "availableUnits": cap.AvailableUnits,
					"cooledCapacityUnits": cap.CooledCapacityUnits, "cooledReservedUnits": cap.CooledReservedUnits, "cooledAvailableUnits": cap.CooledAvailable,
				},
			})
		}
	}

	exceptions := []map[string]interface{}{}
	erows, err := s.DB.Query(r.Context(), `SELECT id, exception FROM samples WHERE status='exception'`)
	if err == nil {
		defer erows.Close()
		for erows.Next() {
			var id string
			var exc []byte
			if erows.Scan(&id, &exc) != nil {
				continue
			}
			exceptions = append(exceptions, map[string]interface{}{"sampleId": id, "exception": rawJSONOrEmpty(exc)})
		}
	}

	routes := []map[string]interface{}{}
	jrows, err := s.DB.Query(r.Context(), `SELECT id, status, route_mode, plan_version, sample_ids FROM journeys WHERE status NOT IN ('cancelled','merged','superseded')`)
	if err == nil {
		defer jrows.Close()
		for jrows.Next() {
			var id, status, mode string
			var version int
			var sids []string
			if jrows.Scan(&id, &status, &mode, &version, &sids) != nil {
				continue
			}
			routes = append(routes, map[string]interface{}{"journeyId": id, "status": status, "routeMode": mode, "planVersion": version, "sampleIds": sids})
		}
	}

	WriteData(w, http.StatusOK, map[string]interface{}{
		"samples": samples, "workers": workers, "locations": locations, "connections": connections,
		"exceptions": exceptions, "routes": routes,
	})
}
"}

{"command":"create","path":"/workspace/backend/internal/server/handlers_audit.go","file_text":"package server

import (
	"fmt"
	"net/http"
	"strings"
	"time"
)

type searchAuditReq struct {
	Query      string `json:"query"`
	ActorID    string `json:"actorId"`
	EntityType string `json:"entityType"`
	EntityID   string `json:"entityId"`
	Action     string `json:"action"`
	Role       string `json:"role"`
	Success    *bool  `json:"success"`
	FromTime   string `json:"fromTime"`
	ToTime     string `json:"toTime"`
	Limit      int    `json:"limit"`
	Offset     int    `json:"offset"`
	Order      string `json:"order"`
}

func (s *Server) HandleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req searchAuditReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	limit := req.Limit
	if limit <= 0 {
		limit = 50
	}
	if limit > 500 {
		limit = 500
	}
	order := "DESC"
	orderName := "newest_first"
	if req.Order == "oldest_first" {
		order = "ASC"
		orderName = "oldest_first"
	}

	var conds []string
	var args []interface{}
	add := func(cond string, val interface{}) {
		args = append(args, val)
		conds = append(conds, fmt.Sprintf(cond, len(args)))
	}
	if req.ActorID != "" {
		add("actor_id = $%d", req.ActorID)
	}
	if req.EntityType != "" {
		add("entity_type = $%d", req.EntityType)
	}
	if req.EntityID != "" {
		add("entity_id = $%d", req.EntityID)
	}
	if req.Action != "" {
		add("action = $%d", req.Action)
	}
	if req.Role != "" {
		add("role = $%d", req.Role)
	}
	if req.Success != nil {
		add("success = $%d", *req.Success)
	}
	if req.FromTime != "" {
		if t, err := time.Parse(time.RFC3339, req.FromTime); err == nil {
			add("occurred_at >= $%d", t)
		}
	}
	if req.ToTime != "" {
		if t, err := time.Parse(time.RFC3339, req.ToTime); err == nil {
			add("occurred_at <= $%d", t)
		}
	}
	if req.Query != "" {
		add("(action ILIKE $%d OR entity_id ILIKE $%d OR actor_id ILIKE $%d)", "%"+req.Query+"%")
		// fix: need same arg repeated 3 times; adjust below
	}
	where := ""
	if len(conds) > 0 {
		where = "WHERE " + strings.Join(conds, " AND ")
	}

	// Rebuild query args correctly for the query-search condition (needs 3 placeholders referencing same value).
	if req.Query != "" {
		lastIdx := len(args)
		where = strings.Replace(where, fmt.Sprintf("$%d OR entity_id ILIKE $%d OR actor_id ILIKE $%d", lastIdx, lastIdx, lastIdx),
			fmt.Sprintf("$%d OR entity_id ILIKE $%d OR actor_id ILIKE $%d", lastIdx, lastIdx, lastIdx), 1)
	}

	var total int
	countQuery := "SELECT COUNT(*) FROM audit_log " + where
	_ = s.DB.QueryRow(r.Context(), countQuery, args...).Scan(&total)

	dataArgs := append(append([]interface{}{}, args...), limit, req.Offset)
	dataQuery := fmt.Sprintf("SELECT id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log %s ORDER BY occurred_at %s LIMIT $%d OFFSET $%d",
		where, order, len(dataArgs)-1, len(dataArgs))

	entries := []map[string]interface{}{}
	rows, err := s.DB.Query(r.Context(), dataQuery, dataArgs...)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var id int64
			var actorID, role, action, entityType, entityID string
			var success bool
			var occurredAt time.Time
			var details []byte
			if rows.Scan(&id, &actorID, &role, &action, &entityType, &entityID, &success, &occurredAt, &details) != nil {
				continue
			}
			entries = append(entries, map[string]interface{}{
				"auditId": fmt.Sprintf("%d", id), "actorId": actorID, "role": role, "actorRole": role,
				"action": action, "entityType": entityType, "entityId": entityID, "success": success,
				"occurredAt": occurredAt.Format(time.RFC3339), "details": rawJSONOrEmpty(details),
			})
		}
	}

	returned := len(entries)
	hasMore := req.Offset+returned < total
	nextOffset := req.Offset + returned

	s.Audit(r.Context(), u.UserID, u.ActiveRole, "search_audit_trail", "audit_log", "search", true, map[string]interface{}{"query": req.Query})

	WriteData(w, http.StatusOK, map[string]interface{}{
		"entries": entries, "total": total, "returned": returned, "offset": req.Offset, "limit": limit,
		"order": orderName, "hasMore": hasMore, "nextOffset": nextOffset,
	})
}
"}

