{"command":"create","path":"/workspace/frontend/src/api.ts","file_text":"// Thin API client for the Lab Sample Pickup & Delivery backend.
// All endpoints are POST (except a few GETs) and return {data: ...} on
// success or {error, code} on failure, per the pinned OpenAPI contract.

export interface ApiError {
  error: string;
  code: string;
  status: number;
}

const BASE = "/api";

function getToken(): string | null {
  return localStorage.getItem("sessionToken");
}

export function setToken(token: string | null) {
  if (token) localStorage.setItem("sessionToken", token);
  else localStorage.removeItem("sessionToken");
}

async function request<T>(
  method: string,
  path: string,
  body?: unknown,
): Promise<T> {
  const headers: Record<string, string> = {};
  const token = getToken();
  if (token) headers["Authorization"] = `Bearer ${token}`;
  if (body !== undefined) headers["Content-Type"] = "application/json";

  const res = await fetch(`${BASE}${path}`, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });

  const text = await res.text();
  const json = text ? JSON.parse(text) : {};

  if (!res.ok) {
    const err: ApiError = {
      error: json.error || res.statusText,
      code: json.code || "unknown_error",
      status: res.status,
    };
    throw err;
  }
  return (json.data ?? json) as T;
}

export const api = {
  get: <T>(path: string) => request<T>("GET", path),
  post: <T>(path: string, body?: unknown) => request<T>("POST", path, body),
};

export function newIdempotencyKey(): string {
  return crypto.randomUUID();
}
"}

{"command":"create","path":"/workspace/frontend/src/AuthContext.tsx","file_text":"import { createContext, useCallback, useContext, useEffect, useState } from "react";
import type { ReactNode } from "react";
import { api, setToken } from "./api";

interface AuthUser {
  userId: string;
  username: string;
  roles: string[];
  activeRole: string;
}

interface LoginResponse {
  sessionToken: string;
  userId: string;
  roles: string[];
  activeRole: string;
}

interface AuthContextValue {
  user: AuthUser | null;
  loading: boolean;
  login: (username: string, password: string) => Promise<void>;
  logout: () => void;
  selectRole: (role: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const stored = localStorage.getItem("authUser");
    if (stored) {
      try {
        setUser(JSON.parse(stored));
      } catch {
        /* ignore malformed cache */
      }
    }
    setLoading(false);
  }, []);

  const persist = useCallback((u: AuthUser | null) => {
    setUser(u);
    if (u) localStorage.setItem("authUser", JSON.stringify(u));
    else localStorage.removeItem("authUser");
  }, []);

  const login = useCallback(
    async (username: string, password: string) => {
      const data = await api.post<LoginResponse>("/authenticate-user", {
        username,
        password,
      });
      setToken(data.sessionToken);
      persist({
        userId: data.userId,
        username,
        roles: data.roles,
        activeRole: data.activeRole,
      });
    },
    [persist],
  );

  const logout = useCallback(() => {
    setToken(null);
    persist(null);
  }, [persist]);

  const selectRole = useCallback(
    async (role: string) => {
      const data = await api.post<{ activeRole: string; roles: string[] }>(
        "/select-active-role",
        { role },
      );
      if (user) {
        persist({ ...user, activeRole: data.activeRole, roles: data.roles });
      }
    },
    [user, persist],
  );

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, selectRole }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
}

export const ROLE_LABELS: Record<string, string> = {
  administrator: "Administrator",
  dispatcher: "Dispatcher",
  requester: "Requester",
  collection_professional: "Certified Collection Professional",
  relay_courier: "Relay Courier",
  node_handler: "Node Handler",
  laboratory_intake_operator: "Laboratory Intake Operator",
};
"}

