{"command":"create","path":"/workspace/frontend/src/pages/DashboardPage.tsx","file_text":"import { useCallback, useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api, newIdempotencyKey } from "../api";
import { useAuth } from "../AuthContext";
import type { ApiError } from "../api";
import type { RoleWorkItem } from "../types";

interface RoleWorkResponse {
  pending?: RoleWorkItem[];
  inProgress?: RoleWorkItem[];
  completed?: RoleWorkItem[];
  [key: string]: unknown;
}

const COMPLETED_STATUSES = new Set([
  "received",
  "cancelled",
  "expired",
  "completed",
  "declined",
]);

export default function DashboardPage() {
  const { user } = useAuth();
  const [work, setWork] = useState<RoleWorkResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await api.post<RoleWorkResponse>("/list-role-work", {});
      setWork(data);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to load work items");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  async function accept(assignmentId: string) {
    setBusyId(assignmentId);
    setActionError(null);
    try {
      await api.post("/accept-assignment", {
        assignmentId,
        idempotencyKey: newIdempotencyKey(),
      });
      await load();
    } catch (err) {
      const e2 = err as ApiError;
      setActionError(e2.error || "Unable to accept assignment");
    } finally {
      setBusyId(null);
    }
  }

  async function decline(assignmentId: string) {
    setBusyId(assignmentId);
    setActionError(null);
    try {
      await api.post("/decline-assignment", {
        assignmentId,
        idempotencyKey: newIdempotencyKey(),
      });
      await load();
    } catch (err) {
      const e2 = err as ApiError;
      setActionError(e2.error || "Unable to decline assignment");
    } finally {
      setBusyId(null);
    }
  }

  if (loading) return <p>Loading work…</p>;
  if (error) return <p role="alert">{error}</p>;
  if (!work) return null;

  const pending = work.pending || [];
  const inProgress = work.inProgress || [];
  const completed = (work.completed || []).filter((item) =>
    COMPLETED_STATUSES.has(item.status),
  );
  const isWorker = user
    ? [
        "collection_professional",
        "delivery_partner",
        "node_handler",
        "laboratory_team",
      ].includes(user.activeRole)
    : false;

  function renderItem(item: RoleWorkItem, section: string) {
    const id = item.sampleId || item.assignmentId || "";
    const link = item.sampleId ? `/samples/${item.sampleId}` : undefined;
    return (
      <li key={`${section}-${id}`} className="work-item">
        <div className="work-item-head">
          <span className="work-kind">{item.kind}</span>
          <span className={`status-pill status-${item.status}`}>
            {item.status}
          </span>
        </div>
        <dl>
          {item.requestId && (
            <div>
              <dt>Request</dt>
              <dd>{item.requestId}</dd>
            </div>
          )}
          {item.sampleId && (
            <div>
              <dt>Sample</dt>
              <dd>{item.sampleId}</dd>
            </div>
          )}
          {item.deliveryDeadline && (
            <div>
              <dt>Deadline</dt>
              <dd>{new Date(item.deliveryDeadline as string).toLocaleString()}</dd>
            </div>
          )}
          {item.serviceability && (
            <div>
              <dt>Serviceability</dt>
              <dd>{item.serviceability}</dd>
            </div>
          )}
        </dl>
        <div className="work-item-actions">
          {link && <Link to={link}>View status history</Link>}
          {section === "pending" &&
            isWorker &&
            item.assignmentId &&
            (item.status === "offered" || item.status === "pending") && (
              <>
                <button
                  type="button"
                  disabled={busyId === item.assignmentId}
                  onClick={() => accept(item.assignmentId!)}
                >
                  Accept
                </button>
                <button
                  type="button"
                  disabled={busyId === item.assignmentId}
                  onClick={() => decline(item.assignmentId!)}
                >
                  Decline
                </button>
              </>
            )}
        </div>
      </li>
    );
  }

  return (
    <div className="dashboard-page">
      <h1>My work — {user?.activeRole}</h1>
      {actionError && <p role="alert">{actionError}</p>}
      <section aria-labelledby="pending-heading">
        <h2 id="pending-heading">Pending / Offered</h2>
        {pending.length === 0 ? (
          <p>Nothing pending.</p>
        ) : (
          <ul className="work-list">
            {pending.map((item) => renderItem(item, "pending"))}
          </ul>
        )}
      </section>
      <section aria-labelledby="progress-heading">
        <h2 id="progress-heading">In progress</h2>
        {inProgress.length === 0 ? (
          <p>Nothing in progress.</p>
        ) : (
          <ul className="work-list">
            {inProgress.map((item) => renderItem(item, "inProgress"))}
          </ul>
        )}
      </section>
      <section aria-labelledby="completed-heading">
        <h2 id="completed-heading">Completed</h2>
        {completed.length === 0 ? (
          <p>No completed work yet.</p>
        ) : (
          <ul className="work-list">
            {completed.map((item) => renderItem(item, "completed"))}
          </ul>
        )}
      </section>
    </div>
  );
}
"}

