            <p>Serviceability: {submitResult.serviceability}</p>
            <button
              type="button"
              onClick={() => navigate(`/samples/${submitResult.sampleId}`)}
            >
              View sample
            </button>
          </div>
        )}
      </form>
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/SampleDetailPage.tsx","file_text":"import { useCallback, useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { api } from "../api";
import type { ApiError } from "../api";
import type { SampleState, TimelineEntry } from "../types";

interface Lifecycle {
  sampleId: string;
  status: string;
  sealed: boolean;
  completedLegIds: string[];
  activeReplacementPlanIds: string[];
  timeline: TimelineEntry[];
  locationStale: boolean;
  activeJourneyId?: string;
  currentHolderId?: string;
  receivedLaboratoryId?: string;
  exception?: Record<string, unknown>;
  pendingHandoffId?: string;
  latestLocation?: { latitude: number; longitude: number };
  locationRecordedAt?: string;
}

export default function SampleDetailPage() {
  const { sampleId } = useParams<{ sampleId: string }>();
  const [sample, setSample] = useState<SampleState | null>(null);
  const [lifecycle, setLifecycle] = useState<Lifecycle | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    if (!sampleId) return;
    setLoading(true);
    setError(null);
    try {
      const [state, life] = await Promise.all([
        api.get<SampleState>(`/read-sample-state/${sampleId}`),
        api.post<Lifecycle>("/read-sample-lifecycle", { sampleId }),
      ]);
      setSample(state);
      setLifecycle(life);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to load sample");
    } finally {
      setLoading(false);
    }
  }, [sampleId]);

  useEffect(() => {
    load();
  }, [load]);

  if (loading) return <p>Loading sample…</p>;
  if (error) return <p role="alert">{error}</p>;
  if (!sample) return null;

  const hasException = !!lifecycle?.exception;

  return (
    <div className="sample-detail-page">
      <h1>Sample {sample.sampleId}</h1>
      {hasException && (
        <div className="banner banner-error" role="alert" aria-label="exception-flag">
          Exception: {JSON.stringify(lifecycle?.exception)}
        </div>
      )}
      <section aria-labelledby="status-heading">
        <h2 id="status-heading">Status</h2>
        <dl className="detail-grid">
          <div>
            <dt>Current status</dt>
            <dd>{sample.state?.status}</dd>
          </div>
          <div>
            <dt>Serviceability</dt>
            <dd>{sample.serviceability}</dd>
          </div>
          <div>
            <dt>Current holder</dt>
            <dd>{lifecycle?.currentHolderId || sample.currentHolderId || "—"}</dd>
          </div>
          <div>
            <dt>Latest location</dt>
            <dd>
              {sample.latestLocation
                ? `${sample.latestLocation.latitude.toFixed(4)}, ${sample.latestLocation.longitude.toFixed(4)}`
                : "Unknown"}
            </dd>
          </div>
          <div>
            <dt>Last updated</dt>
            <dd>
              {sample.locationRecordedAt
                ? new Date(sample.locationRecordedAt).toLocaleString()
                : "—"}
            </dd>
          </div>
          <div>
            <dt>Location freshness</dt>
            <dd aria-label="location-stale-flag">
              {sample.locationStale ? "Stale" : "Fresh"}
            </dd>
          </div>
          <div>
            <dt>Delivery deadline</dt>
            <dd>{new Date(sample.deliveryDeadline).toLocaleString()}</dd>
          </div>
          <div>
            <dt>Active journey</dt>
            <dd>{sample.activeJourneyId || "—"}</dd>
          </div>
        </dl>
      </section>

      <section aria-labelledby="history-heading">
        <h2 id="history-heading">Status timeline</h2>
        {sample.timeline && sample.timeline.length > 0 ? (
          <ol className="timeline">
            {sample.timeline.map((entry, idx) => (
              <li key={entry.eventId ?? idx}>
                <span className="timeline-time">
                  {new Date(entry.occurredAt).toLocaleString()}
                </span>
                <span className="timeline-action">{entry.action}</span>
                <span className="timeline-role">({entry.role})</span>
                <span
                  className={`timeline-outcome ${
                    entry.success ? "outcome-ok" : "outcome-fail"
                  }`}
                >
                  {entry.success ? "success" : "failed"}
                </span>
              </li>
            ))}
          </ol>
        ) : (
          <p>No status history yet.</p>
        )}
      </section>
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/MapPage.tsx","file_text":"import { useEffect, useRef, useState } from "react";
import maplibregl from "maplibre-gl";
import { Protocol } from "pmtiles";
import "maplibre-gl/dist/maplibre-gl.css";
import { api } from "../api";
import { useAuth } from "../AuthContext";
import type { OperationsState } from "../types";

let protocolRegistered = false;

export default function MapPage() {
  const { user } = useAuth();
  const mapContainer = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [ready, setReady] = useState(false);

  const canSeeOperations = user
    ? user.activeRole === "dispatcher" || user.activeRole === "administrator"
    : false;

  useEffect(() => {
    if (!protocolRegistered) {
      const protocol = new Protocol();
      maplibregl.addProtocol("pmtiles", protocol.tile);
      protocolRegistered = true;
    }
    if (!mapContainer.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: "/map-assets/style.json",
      center: [77.5946, 12.9716],
      zoom: 11,
    });
    mapRef.current = map;
    map.on("load", () => setReady(true));
    map.on("error", (e) => {
      setError(e.error?.message || "Map failed to load");
    });

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (!ready || !canSeeOperations) return;
    const map = mapRef.current;
    if (!map) return;

    let cancelled = false;
    const markers: maplibregl.Marker[] = [];

    async function loadOperations() {
      try {
        const data = await api.post<OperationsState>("/read-operations-state", {});
        if (cancelled) return;
        markers.forEach((m) => m.remove());
        markers.length = 0;

        data.locations?.forEach((loc) => {
          if (!loc.coordinate) return;
          const el = document.createElement("div");
          el.className = "map-marker map-marker-location";
          el.title = loc.name;
          const marker = new maplibregl.Marker({ element: el })
            .setLngLat([loc.coordinate.longitude, loc.coordinate.latitude])
            .setPopup(new maplibregl.Popup().setText(loc.name))
            .addTo(map);
          markers.push(marker);
        });

        data.workers?.forEach((worker) => {
          if (!worker.latestLocation) return;
          const el = document.createElement("div");
          el.className = "map-marker map-marker-worker";
          el.title = worker.fullName || worker.workerId;
          const marker = new maplibregl.Marker({ element: el, color: "#2563eb" })
            .setLngLat([
              worker.latestLocation.longitude,
              worker.latestLocation.latitude,
            ])
            .setPopup(
              new maplibregl.Popup().setText(
                `${worker.fullName || worker.workerId} — ${
                  worker.locationStale ? "stale" : "fresh"
                }`,
              ),
            )
            .addTo(map);
          markers.push(marker);
        });
      } catch {
        /* operations view is optional on this page */
      }
    }

    loadOperations();
    const interval = setInterval(loadOperations, 15000);
    return () => {
      cancelled = true;
      clearInterval(interval);
      markers.forEach((m) => m.remove());
    };
  }, [ready, canSeeOperations]);

  return (
    <div className="map-page">
      <h1>Live map</h1>
      {error && <p role="alert">{error}</p>}
      <div
        ref={mapContainer}
        className="map-container"
        role="region"
        aria-label="Live map of routes, nodes and worker locations"
        style={{ width: "100%", height: "70vh" }}
      />
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/MonitorPage.tsx","file_text":"import { useCallback, useEffect, useState } from "react";
import { api, newIdempotencyKey } from "../api";
import type { ApiError } from "../api";
import type { OperationsState } from "../types";

const RESOURCE_TYPES = [
  "location",
  "node",
  "laboratory",
  "connection",
  "route",
  "worker",
  "capacity",
];

export default function MonitorPage() {
  const [state, setState] = useState<OperationsState | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const [journeyId, setJourneyId] = useState("");
  const [planVersion, setPlanVersion] = useState("1");
  const [reason, setReason] = useState("");
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionResult, setActionResult] = useState<string | null>(null);

  const [resourceType, setResourceType] = useState(RESOURCE_TYPES[0]);
  const [resourceId, setResourceId] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await api.post<OperationsState>("/read-operations-state", {});
      setState(data);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to load operations state");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
    const id = setInterval(load, 20000);
    return () => clearInterval(id);
  }, [load]);

  async function onReroute() {
    setActionError(null);
    setActionResult(null);
    try {
      const data = await api.post<{ journeyId: string; replanStatus: string }>(
        "/reroute-journey",
        {
          journeyId,
          expectedPlanVersion: parseInt(planVersion, 10),
          reason: reason || undefined,
          idempotencyKey: newIdempotencyKey(),
        },
      );
      setActionResult(`Reroute status: ${data.replanStatus}`);
      load();
    } catch (err) {
      const e2 = err as ApiError;
      setActionError(e2.error || "Unable to reroute journey");
    }
  }

  async function onCancel() {
    setActionError(null);
    setActionResult(null);
    try {
      const data = await api.post<{ status: string }>("/cancel-journey", {
        journeyId,
        expectedPlanVersion: parseInt(planVersion, 10),
        reason: reason || undefined,
        idempotencyKey: newIdempotencyKey(),
      });
      setActionResult(`Journey ${data.status}`);
      load();
    } catch (err) {
      const e2 = err as ApiError;
      setActionError(e2.error || "Unable to cancel journey");
    }
  }

  async function onReportDisruption() {
    setActionError(null);
    setActionResult(null);
    try {
      const data = await api.post<{ replanStatus: string }>(
        "/report-disruption",
        {
          resourceType,
          resourceId,
          reason: reason || undefined,
          occurredAt: new Date().toISOString(),
          idempotencyKey: newIdempotencyKey(),
        },
      );
      setActionResult(`Replan status: ${data.replanStatus}`);
      load();
    } catch (err) {
      const e2 = err as ApiError;
      setActionError(e2.error || "Unable to report disruption");
    }
  }

  if (loading) return <p>Loading operations…</p>;
  if (error) return <p role="alert">{error}</p>;
  if (!state) return null;

  return (
    <div className="monitor-page">
      <h1>Dispatch monitor</h1>
      <div className="monitor-grid">
        <section aria-labelledby="samples-heading">
          <h2 id="samples-heading">Samples ({state.samples.length})</h2>
          <ul className="monitor-list">
            {state.samples.map((s) => (
              <li key={s.sampleId}>
                <strong>{s.sampleId}</strong> — {s.status}{" "}
                {s.locationStale && <span className="badge badge-stale">stale</span>}
                <div className="muted">Holder: {s.currentHolderId || "—"}</div>
              </li>
            ))}
          </ul>
        </section>

        <section aria-labelledby="workers-heading">
          <h2 id="workers-heading">Workers ({state.workers.length})</h2>
          <ul className="monitor-list">
            {state.workers.map((w) => (
              <li key={w.workerId}>
                <strong>{w.fullName || w.workerId}</strong> — {w.status}{" "}
                <span className="muted">
                  ({w.assignmentCount} assignments, {w.roles.join(", ")})
                </span>
                {w.locationStale && <span className="badge badge-stale">stale</span>}
              </li>
            ))}
          </ul>
        </section>

        <section aria-labelledby="locations-heading">
          <h2 id="locations-heading">Nodes &amp; laboratories ({state.locations.length})</h2>
          <ul className="monitor-list">
            {state.locations.map((l) => (
              <li key={l.id}>
                <strong>{l.name}</strong> — {l.active ? "active" : "inactive"}
                <div className="muted">
                  Regular {l.capacity?.availableUnits}/{l.capacity?.capacityUnits} · Cooled{" "}
                  {l.capacity?.cooledAvailableUnits}/{l.capacity?.cooledCapacityUnits}
                </div>
              </li>
            ))}
          </ul>
        </section>

        <section aria-labelledby="connections-heading">
          <h2 id="connections-heading">Routes ({state.connections.length})</h2>
          <ul className="monitor-list">
            {state.connections.map((c) => (
              <li key={c.id}>
                {c.fromLocationId} → {c.toLocationId} — {c.active ? "active" : "inactive"}
              </li>
            ))}
          </ul>
        </section>

        <section aria-labelledby="exceptions-heading">
          <h2 id="exceptions-heading">Exceptions ({state.exceptions.length})</h2>
          <ul className="monitor-list">
            {state.exceptions.map((e, i) => (
              <li key={i}>{JSON.stringify(e)}</li>
            ))}
          </ul>
        </section>
      </div>

      <section aria-labelledby="replan-heading" className="replan-panel">
        <h2 id="replan-heading">Replan &amp; disruption tools</h2>
        {actionError && <p role="alert">{actionError}</p>}
        {actionResult && <p role="status">{actionResult}</p>}
        <div className="replan-form">
          <label htmlFor="journeyId">Journey ID</label>
          <input id="journeyId" value={journeyId} onChange={(e) => setJourneyId(e.target.value)} />
          <label htmlFor="planVersion">Expected plan version</label>
          <input
            id="planVersion"
            type="number"
            min={1}
            value={planVersion}
            onChange={(e) => setPlanVersion(e.target.value)}
          />
          <label htmlFor="reason">Reason</label>
          <input id="reason" value={reason} onChange={(e) => setReason(e.target.value)} />
          <div className="form-actions">
            <button type="button" onClick={onReroute}>
              Reroute journey
            </button>
            <button type="button" onClick={onCancel}>
              Cancel journey
            </button>
          </div>
        </div>
        <div className="replan-form">
          <label htmlFor="resourceType">Disrupted resource type</label>
          <select id="resourceType" value={resourceType} onChange={(e) => setResourceType(e.target.value)}>
            {RESOURCE_TYPES.map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
          <label htmlFor="resourceId">Resource ID</label>
          <input id="resourceId" value={resourceId} onChange={(e) => setResourceId(e.target.value)} />
          <button type="button" onClick={onReportDisruption}>
            Report disruption
          </button>
        </div>
      </section>
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/AuditPage.tsx","file_text":"import { useState } from "react";
import { api } from "../api";
import type { ApiError } from "../api";
import type { AuditEntry } from "../types";

interface AuditSearchResult {
  entries: AuditEntry[];
  total?: number;
  [key: string]: unknown;
}

export default function AuditPage() {
  const [query, setQuery] = useState("");
  const [entityId, setEntityId] = useState("");
  const [action, setAction] = useState("");
  const [results, setResults] = useState<AuditEntry[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [searched, setSearched] = useState(false);

  async function onSearch(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const data = await api.post<AuditSearchResult | AuditEntry[]>(
        "/search-audit-trail",
        {
          query: query || undefined,
          entityId: entityId || undefined,
          action: action || undefined,
          order: "newest_first",
          limit: 100,
        },
      );
      const entries = Array.isArray(data) ? data : data.entries || [];
      setResults(entries);
      setSearched(true);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Search failed");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="audit-page">
      <h1>Audit trail</h1>
      <form onSubmit={onSearch} className="audit-form">
        <label htmlFor="query">Free text</label>
        <input id="query" value={query} onChange={(e) => setQuery(e.target.value)} />
        <label htmlFor="entityId">Entity ID (sample, request, journey…)</label>
        <input id="entityId" value={entityId} onChange={(e) => setEntityId(e.target.value)} />
        <label htmlFor="action">Action</label>
        <input id="action" value={action} onChange={(e) => setAction(e.target.value)} />
        <button type="submit" disabled={loading}>
          {loading ? "Searching…" : "Search"}
        </button>
      </form>
      {error && <p role="alert">{error}</p>}
      {searched && (
        <table className="audit-table">
          <thead>
            <tr>
              <th>Time</th>
              <th>User</th>
              <th>Role</th>
              <th>Action</th>
              <th>Entity</th>
              <th>Outcome</th>
            </tr>
          </thead>
          <tbody>
            {results.map((entry, idx) => (
              <tr key={entry.auditId ?? idx}>
                <td>{new Date(entry.occurredAt).toLocaleString()}</td>
                <td>{entry.actorId}</td>
                <td>{entry.role}</td>
                <td>{entry.action}</td>
                <td>
                  {entry.entityType}:{entry.entityId}
                </td>
                <td>{entry.success ? "success" : "failed"}</td>
              </tr>
            ))}
            {results.length === 0 && (
              <tr>
                <td colSpan={6}>No matching audit records.</td>
              </tr>
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}
