{"command":"create","path":"/workspace/frontend/src/pages/AdminUsersPage.tsx","file_text":"import { useState } from "react";
import { api } from "../api";
import type { ApiError } from "../api";

const ROLES = [
  "administrator",
  "dispatcher",
  "requester",
  "collection_professional",
  "delivery_partner",
  "node_handler",
  "laboratory_team",
];

interface UserRecord {
  userId: string;
  username: string;
  email?: string;
  fullName?: string;
  phone?: string;
  roles: string[];
  qualifications: string[];
  certifications: unknown[];
  active: boolean;
}

export default function AdminUsersPage() {
  const [username, setUsername] = useState("");
  const [initialPassword, setInitialPassword] = useState("");
  const [email, setEmail] = useState("");
  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");
  const [roles, setRoles] = useState<string[]>([]);
  const [qualifications, setQualifications] = useState("");
  const [assignedLocationId, setAssignedLocationId] = useState("");
  const [active, setActive] = useState(true);

  const [lookupId, setLookupId] = useState("");
  const [lookupResult, setLookupResult] = useState<UserRecord | null>(null);
  const [updateRoles, setUpdateRoles] = useState<string[]>([]);
  const [updateActive, setUpdateActive] = useState(true);
  const [updateLocationId, setUpdateLocationId] = useState("");

  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  function toggleRole(list: string[], setList: (v: string[]) => void, role: string) {
    setList(list.includes(role) ? list.filter((r) => r !== role) : [...list, role]);
  }

  async function onCreateUser(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      const data = await api.post<UserRecord>("/create-user", {
        username,
        initialPassword,
        email: email || undefined,
        fullName: fullName || undefined,
        phone: phone || undefined,
        roles,
        qualifications: qualifications
          ? qualifications.split(",").map((q) => q.trim()).filter(Boolean)
          : undefined,
        active,
        assignedLocationId: assignedLocationId || undefined,
      });
      setMessage(`Created user ${data.username} (${data.userId})`);
      setUsername("");
      setInitialPassword("");
      setEmail("");
      setFullName("");
      setPhone("");
      setRoles([]);
      setQualifications("");
      setAssignedLocationId("");
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to create user");
    }
  }

  async function onLookup(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      const data = await api.get<UserRecord>(`/read-user/${lookupId}`);
      setLookupResult(data);
      setUpdateRoles(data.roles);
      setUpdateActive(data.active);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "User not found");
      setLookupResult(null);
    }
  }

  async function onUpdateAccess() {
    if (!lookupResult) return;
    setError(null);
    setMessage(null);
    try {
      const data = await api.post<UserRecord>("/update-user-access", {
        userId: lookupResult.userId,
        roles: updateRoles,
        active: updateActive,
        assignedLocationId: updateLocationId || undefined,
      });
      setMessage(`Updated access for ${lookupResult.username}`);
      setLookupResult({ ...lookupResult, roles: data.roles, active: data.active });
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to update access");
    }
  }

  return (
    <div className="admin-users-page">
      <h1>User management</h1>
      {error && <p role="alert">{error}</p>}
      {message && <p role="status">{message}</p>}

      <section aria-labelledby="create-user-heading">
        <h2 id="create-user-heading">Create user</h2>
        <form onSubmit={onCreateUser} className="stacked-form">
          <label htmlFor="username">Username</label>
          <input id="username" value={username} onChange={(e) => setUsername(e.target.value)} required />

          <label htmlFor="initialPassword">Initial password</label>
          <input
            id="initialPassword"
            type="password"
            value={initialPassword}
            onChange={(e) => setInitialPassword(e.target.value)}
            required
          />

          <label htmlFor="fullName">Full name</label>
          <input id="fullName" value={fullName} onChange={(e) => setFullName(e.target.value)} />

          <label htmlFor="email">Email</label>
          <input id="email" value={email} onChange={(e) => setEmail(e.target.value)} />

          <label htmlFor="phone">Phone</label>
          <input id="phone" value={phone} onChange={(e) => setPhone(e.target.value)} />

          <fieldset>
            <legend>Roles</legend>
            {ROLES.map((r) => (
              <label key={r} className="checkbox-label">
                <input
                  type="checkbox"
                  checked={roles.includes(r)}
                  onChange={() => toggleRole(roles, setRoles, r)}
                />
                {r}
              </label>
            ))}
          </fieldset>

          <label htmlFor="qualifications">Qualifications (comma-separated)</label>
          <input
            id="qualifications"
            value={qualifications}
            onChange={(e) => setQualifications(e.target.value)}
            placeholder="Amber, Indigo, Frost, Pulse"
          />

          <label htmlFor="assignedLocationId">Assigned node/laboratory ID</label>
          <input
            id="assignedLocationId"
            value={assignedLocationId}
            onChange={(e) => setAssignedLocationId(e.target.value)}
          />

          <label className="checkbox-label">
            <input type="checkbox" checked={active} onChange={(e) => setActive(e.target.checked)} />
            Active
          </label>

          <button type="submit">Create user</button>
        </form>
      </section>

      <section aria-labelledby="edit-user-heading">
        <h2 id="edit-user-heading">Manage roles &amp; certifications</h2>
        <form onSubmit={onLookup} className="inline-form">
          <label htmlFor="lookupId">User ID</label>
          <input id="lookupId" value={lookupId} onChange={(e) => setLookupId(e.target.value)} required />
          <button type="submit">Look up</button>
        </form>

        {lookupResult && (
          <div className="edit-user-panel">
            <h3>{lookupResult.username}</h3>
            <fieldset>
              <legend>Roles</legend>
              {ROLES.map((r) => (
                <label key={r} className="checkbox-label">
                  <input
                    type="checkbox"
                    checked={updateRoles.includes(r)}
                    onChange={() => toggleRole(updateRoles, setUpdateRoles, r)}
                  />
                  {r}
                </label>
              ))}
            </fieldset>
            <label htmlFor="updateLocationId">Assigned node/laboratory ID</label>
            <input
              id="updateLocationId"
              value={updateLocationId}
              onChange={(e) => setUpdateLocationId(e.target.value)}
            />
            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={updateActive}
                onChange={(e) => setUpdateActive(e.target.checked)}
              />
              Active
            </label>
            <button type="button" onClick={onUpdateAccess}>
              Save access
            </button>
          </div>
        )}
      </section>
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/AdminNetworkPage.tsx","file_text":"import { useState } from "react";
import { api } from "../api";
import type { ApiError } from "../api";

const FUNCTIONS = ["collection_point", "transfer_point", "hub", "laboratory"];

export default function AdminNetworkPage() {
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  const [locName, setLocName] = useState("");
  const [lat, setLat] = useState("");
  const [lon, setLon] = useState("");
  const [coverageKm, setCoverageKm] = useState("5");
  const [handlingMinutes, setHandlingMinutes] = useState("15");
  const [functions, setFunctions] = useState<string[]>([]);
  const [locActive, setLocActive] = useState(true);

  const [fromLocationId, setFromLocationId] = useState("");
  const [toLocationId, setToLocationId] = useState("");
  const [travelMinutes, setTravelMinutes] = useState("30");
  const [costUnits, setCostUnits] = useState("1");
  const [cooled, setCooled] = useState(false);
  const [connActive, setConnActive] = useState(true);

  const [statusLocationId, setStatusLocationId] = useState("");
  const [statusFunction, setStatusFunction] = useState(FUNCTIONS[0]);
  const [statusConnectionId, setStatusConnectionId] = useState("");

  const [labId, setLabId] = useState("");
  const [labSampleTypeId, setLabSampleTypeId] = useState("");
  const [labAccepts, setLabAccepts] = useState(true);

  function toggleFn(fn: string) {
    setFunctions((prev) => (prev.includes(fn) ? prev.filter((f) => f !== fn) : [...prev, fn]));
  }

  async function onCreateLocation(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      await api.post("/create-location", {
        name: locName,
        coordinate: { latitude: parseFloat(lat), longitude: parseFloat(lon) },
        coverageKm: parseFloat(coverageKm),
        handlingMinutes: parseInt(handlingMinutes, 10),
        active: locActive,
        functions,
      });
      setMessage(`Created location ${locName}`);
      setLocName("");
      setLat("");
      setLon("");
      setFunctions([]);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to create location");
    }
  }

  async function onCreateConnection(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      const data = await api.post<{ connectionId: string }>("/create-connection", {
        fromLocationId,
        toLocationId,
        travelMinutes: parseInt(travelMinutes, 10),
        costUnits: parseFloat(costUnits),
        cooled,
        active: connActive,
      });
      setMessage(`Created connection ${data.connectionId}`);
      setFromLocationId("");
      setToLocationId("");
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to create connection");
    }
  }

  async function onSetLocationStatus(active: boolean) {
    setError(null);
    setMessage(null);
    try {
      await api.post("/set-location-status", { locationId: statusLocationId, active });
      setMessage(`Location ${statusLocationId} set ${active ? "active" : "inactive"}`);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to set location status");
    }
  }

  async function onSetFunctionStatus(active: boolean) {
    setError(null);
    setMessage(null);
    try {
      await api.post("/set-location-function-status", {
        locationId: statusLocationId,
        function: statusFunction,
        active,
      });
      setMessage(`Function ${statusFunction} set ${active ? "active" : "inactive"}`);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to set function status");
    }
  }

  async function onSetConnectionStatus(active: boolean) {
    setError(null);
    setMessage(null);
    try {
      await api.post("/set-connection-status", { connectionId: statusConnectionId, active });
      setMessage(`Connection ${statusConnectionId} set ${active ? "active" : "inactive"}`);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to set connection status");
    }
  }

  async function onConfigureLabAcceptance(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      await api.post("/configure-laboratory-acceptance", {
        laboratoryId: labId,
        sampleTypeId: labSampleTypeId,
        accepts: labAccepts,
      });
      setMessage(`Updated acceptance for laboratory ${labId}`);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to configure laboratory acceptance");
    }
  }

  return (
    <div className="admin-network-page">
      <h1>Network configuration</h1>
      {error && <p role="alert">{error}</p>}
      {message && <p role="status">{message}</p>}

      <section aria-labelledby="create-location-heading">
        <h2 id="create-location-heading">Create location</h2>
        <form onSubmit={onCreateLocation} className="stacked-form">
          <label htmlFor="locName">Name</label>
          <input id="locName" value={locName} onChange={(e) => setLocName(e.target.value)} required />
          <label htmlFor="lat">Latitude</label>
          <input id="lat" value={lat} onChange={(e) => setLat(e.target.value)} required />
          <label htmlFor="lon">Longitude</label>
          <input id="lon" value={lon} onChange={(e) => setLon(e.target.value)} required />
          <label htmlFor="coverageKm">Coverage (km)</label>
          <input id="coverageKm" value={coverageKm} onChange={(e) => setCoverageKm(e.target.value)} />
          <label htmlFor="handlingMinutes">Handling minutes</label>
          <input
            id="handlingMinutes"
            value={handlingMinutes}
            onChange={(e) => setHandlingMinutes(e.target.value)}
          />
          <fieldset>
            <legend>Functions</legend>
            {FUNCTIONS.map((fn) => (
              <label key={fn} className="checkbox-label">
                <input type="checkbox" checked={functions.includes(fn)} onChange={() => toggleFn(fn)} />
                {fn}
              </label>
            ))}
          </fieldset>
          <label className="checkbox-label">
            <input type="checkbox" checked={locActive} onChange={(e) => setLocActive(e.target.checked)} />
            Active
          </label>
          <button type="submit">Create location</button>
        </form>
      </section>

      <section aria-labelledby="create-connection-heading">
        <h2 id="create-connection-heading">Create connection</h2>
        <form onSubmit={onCreateConnection} className="stacked-form">
          <label htmlFor="fromLocationId">From location ID</label>
          <input
            id="fromLocationId"
            value={fromLocationId}
            onChange={(e) => setFromLocationId(e.target.value)}
            required
          />
          <label htmlFor="toLocationId">To location ID</label>
          <input
            id="toLocationId"
            value={toLocationId}
            onChange={(e) => setToLocationId(e.target.value)}
            required
          />
          <label htmlFor="travelMinutes">Travel minutes</label>
          <input id="travelMinutes" value={travelMinutes} onChange={(e) => setTravelMinutes(e.target.value)} />
          <label htmlFor="costUnits">Cost units</label>
          <input id="costUnits" value={costUnits} onChange={(e) => setCostUnits(e.target.value)} />
          <label className="checkbox-label">
            <input type="checkbox" checked={cooled} onChange={(e) => setCooled(e.target.checked)} />
            Cooled
          </label>
          <label className="checkbox-label">
            <input type="checkbox" checked={connActive} onChange={(e) => setConnActive(e.target.checked)} />
            Active
          </label>
          <button type="submit">Create connection</button>
        </form>
      </section>

      <section aria-labelledby="status-heading">
        <h2 id="status-heading">Activate / deactivate</h2>
        <div className="stacked-form">
          <label htmlFor="statusLocationId">Location ID</label>
          <input
            id="statusLocationId"
            value={statusLocationId}
            onChange={(e) => setStatusLocationId(e.target.value)}
          />
          <div className="form-actions">
            <button type="button" onClick={() => onSetLocationStatus(true)}>
              Activate location
            </button>
            <button type="button" onClick={() => onSetLocationStatus(false)}>
              Deactivate location
            </button>
          </div>

          <label htmlFor="statusFunction">Function</label>
          <select id="statusFunction" value={statusFunction} onChange={(e) => setStatusFunction(e.target.value)}>
            {FUNCTIONS.map((fn) => (
              <option key={fn} value={fn}>
                {fn}
              </option>
            ))}
          </select>
          <div className="form-actions">
            <button type="button" onClick={() => onSetFunctionStatus(true)}>
              Activate function
            </button>
            <button type="button" onClick={() => onSetFunctionStatus(false)}>
              Deactivate function
            </button>
          </div>

          <label htmlFor="statusConnectionId">Connection ID</label>
          <input
            id="statusConnectionId"
            value={statusConnectionId}
            onChange={(e) => setStatusConnectionId(e.target.value)}
          />
          <div className="form-actions">
            <button type="button" onClick={() => onSetConnectionStatus(true)}>
              Activate connection
            </button>
            <button type="button" onClick={() => onSetConnectionStatus(false)}>
              Deactivate connection
            </button>
          </div>
        </div>
      </section>

      <section aria-labelledby="lab-acceptance-heading">
        <h2 id="lab-acceptance-heading">Laboratory sample-type acceptance</h2>
        <form onSubmit={onConfigureLabAcceptance} className="stacked-form">
          <label htmlFor="labId">Laboratory ID</label>
          <input id="labId" value={labId} onChange={(e) => setLabId(e.target.value)} required />
          <label htmlFor="labSampleTypeId">Sample type ID</label>
          <input
            id="labSampleTypeId"
            value={labSampleTypeId}
            onChange={(e) => setLabSampleTypeId(e.target.value)}
            required
          />
          <label className="checkbox-label">
            <input type="checkbox" checked={labAccepts} onChange={(e) => setLabAccepts(e.target.checked)} />
            Accepts this sample type
          </label>
          <button type="submit">Save acceptance</button>
        </form>
      </section>
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/AdminSampleTypesPage.tsx","file_text":"import { useState } from "react";
import { api } from "../api";
import type { ApiError } from "../api";

interface SampleTypeRecord {
  sampleTypeId: string;
  name: string;
  qualifiedCollectorRequired: boolean;
  requiredQualification: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  incompatibleSampleTypes: string[];
  requiresCooledRoute: boolean;
  batchingAllowed: boolean;
}

export default function AdminSampleTypesPage() {
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [created, setCreated] = useState<SampleTypeRecord[]>([]);

  const [name, setName] = useState("");
  const [qualifiedCollectorRequired, setQualifiedCollectorRequired] = useState(false);
  const [requiredQualification, setRequiredQualification] = useState("");
  const [containerType, setContainerType] = useState("");
  const [temperatureMinC, setTemperatureMinC] = useState("2");
  const [temperatureMaxC, setTemperatureMaxC] = useState("8");
  const [incompatible, setIncompatible] = useState("");
  const [requiresCooledRoute, setRequiresCooledRoute] = useState(false);
  const [batchingAllowed, setBatchingAllowed] = useState(true);

  const [editId, setEditId] = useState("");

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    const payload = {
      name,
      qualifiedCollectorRequired,
      requiredQualification: requiredQualification || undefined,
      containerType,
      temperatureMinC: parseFloat(temperatureMinC),
      temperatureMaxC: parseFloat(temperatureMaxC),
      incompatibleSampleTypes: incompatible
        ? incompatible.split(",").map((s) => s.trim()).filter(Boolean)
        : undefined,
      requiresCooledRoute,
      batchingAllowed,
    };
    try {
      if (editId) {
        const data = await api.post<SampleTypeRecord>("/update-sample-type", {
          sampleTypeId: editId,
          ...payload,
        });
        setMessage(`Updated sample type ${data.name}`);
        setCreated((prev) => prev.map((s) => (s.sampleTypeId === data.sampleTypeId ? data : s)));
      } else {
        const data = await api.post<SampleTypeRecord>("/create-sample-type", payload);
        setMessage(`Created sample type ${data.name} (${data.sampleTypeId})`);
        setCreated((prev) => [...prev, data]);
      }
      setName("");
      setRequiredQualification("");
      setContainerType("");
      setIncompatible("");
      setEditId("");
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to save sample type");
    }
  }

  function loadForEdit(s: SampleTypeRecord) {
    setEditId(s.sampleTypeId);
    setName(s.name);
    setQualifiedCollectorRequired(s.qualifiedCollectorRequired);
    setRequiredQualification(s.requiredQualification || "");
    setContainerType(s.containerType);
    setTemperatureMinC(String(s.temperatureMinC));
    setTemperatureMaxC(String(s.temperatureMaxC));
    setIncompatible((s.incompatibleSampleTypes || []).join(", "));
    setRequiresCooledRoute(s.requiresCooledRoute);
    setBatchingAllowed(s.batchingAllowed);
  }

  return (
    <div className="admin-sample-types-page">
      <h1>Sample types</h1>
      <p className="muted">
        Default types Amber, Indigo, Frost, Pulse are seeded on reset. Use this form to add or amend
        types and their handling attributes.
      </p>
      {error && <p role="alert">{error}</p>}
      {message && <p role="status">{message}</p>}

      <form onSubmit={onSubmit} className="stacked-form">
        <label htmlFor="stName">Name</label>
        <input id="stName" value={name} onChange={(e) => setName(e.target.value)} required disabled={!!editId} />

        <label className="checkbox-label">
          <input
            type="checkbox"
            checked={qualifiedCollectorRequired}
            onChange={(e) => setQualifiedCollectorRequired(e.target.checked)}
          />
          Requires qualified collector
        </label>

        <label htmlFor="requiredQualification">Required qualification</label>
        <input
          id="requiredQualification"
          value={requiredQualification}
          onChange={(e) => setRequiredQualification(e.target.value)}
        />

        <label htmlFor="containerType">Container type</label>
        <input id="containerType" value={containerType} onChange={(e) => setContainerType(e.target.value)} required />

        <label htmlFor="temperatureMinC">Min temperature (°C)</label>
        <input id="temperatureMinC" value={temperatureMinC} onChange={(e) => setTemperatureMinC(e.target.value)} required />

        <label htmlFor="temperatureMaxC">Max temperature (°C)</label>
        <input id="temperatureMaxC" value={temperatureMaxC} onChange={(e) => setTemperatureMaxC(e.target.value)} required />

        <label htmlFor="incompatible">Incompatible sample type IDs (comma-separated)</label>
        <input id="incompatible" value={incompatible} onChange={(e) => setIncompatible(e.target.value)} />

        <label className="checkbox-label">
          <input
            type="checkbox"
            checked={requiresCooledRoute}
            onChange={(e) => setRequiresCooledRoute(e.target.checked)}
          />
          Requires cooled route throughout journey
        </label>

        <label className="checkbox-label">
          <input
            type="checkbox"
            checked={batchingAllowed}
            onChange={(e) => setBatchingAllowed(e.target.checked)}
          />
          Batching allowed
        </label>

        <button type="submit">{editId ? "Update sample type" : "Create sample type"}</button>
        {editId && (
          <button type="button" onClick={() => setEditId("")}>
            Cancel edit
          </button>
        )}
      </form>

      {created.length > 0 && (
        <section aria-labelledby="created-heading">
          <h2 id="created-heading">Sample types configured this session</h2>
          <ul className="monitor-list">
            {created.map((s) => (
              <li key={s.sampleTypeId}>
                <strong>{s.name}</strong> ({s.sampleTypeId}) — {s.containerType},{" "}
                {s.temperatureMinC}–{s.temperatureMaxC}°C
                <button type="button" onClick={() => loadForEdit(s)}>
                  Edit
                </button>
              </li>
            ))}
          </ul>
        </section>
      )}
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/CapacityPage.tsx","file_text":"import { useState } from "react";
import { useAuth } from "../AuthContext";
import { api } from "../api";
import type { ApiError } from "../api";

interface CapacityResult {
  resourceId: string;
  capacityUnits: number;
  cooledCapacityUnits: number;
}

export default function CapacityPage() {
  const { user } = useAuth();
  const [resourceId, setResourceId] = useState("");
  const [capacityUnits, setCapacityUnits] = useState("10");
  const [cooledCapacityUnits, setCooledCapacityUnits] = useState("0");
  const [result, setResult] = useState<CapacityResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    try {
      const data = await api.post<CapacityResult>("/configure-capacity", {
        resourceId,
        capacityUnits: parseInt(capacityUnits, 10),
        cooledCapacityUnits: parseInt(cooledCapacityUnits, 10),
      });
      setResult(data);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to configure capacity");
    }
  }

  return (
    <div className="capacity-page">
      <h1>Node / laboratory capacity</h1>
      <p className="muted">
        {user?.activeRole === "administrator"
          ? "As an administrator you may configure capacity for any node, laboratory or connection."
          : "You may configure capacity for the node or laboratory you are assigned to."}
      </p>
      {error && <p role="alert">{error}</p>}
      {result && (
        <p role="status">
          Regular capacity: {result.capacityUnits} · Cooled capacity: {result.cooledCapacityUnits}
        </p>
      )}
      <form onSubmit={onSubmit} className="stacked-form">
        <label htmlFor="resourceId">Node / laboratory / connection ID</label>
        <input id="resourceId" value={resourceId} onChange={(e) => setResourceId(e.target.value)} required />

        <label htmlFor="capacityUnits">Regular capacity units</label>
        <input
          id="capacityUnits"
          type="number"
          min={0}
          value={capacityUnits}
          onChange={(e) => setCapacityUnits(e.target.value)}
          required
        />

        <label htmlFor="cooledCapacityUnits">Cooled capacity units</label>
        <input
          id="cooledCapacityUnits"
          type="number"
          min={0}
          value={cooledCapacityUnits}
          onChange={(e) => setCooledCapacityUnits(e.target.value)}
        />

        <button type="submit">Save capacity</button>
      </form>
    </div>
  );
}
"}

